// 克洛格截图+中文解法（v1.1.1 简化版）
var BOTW_KOROKS = {"meta":{"name":"Korok Seeds","version":"1.1.1","total":900},"types":[],"items":[{"id":"Seed001","no":1,"hint_en":"Jump from the promontory into the circle of lilies.","hint_cn":"从悬崖跳入睡莲圈","img":"Korok001.jpg"},{"id":"Seed002","no":2,"hint_en":"Lift the rock on this small island.","hint_cn":"举起小岛上的石头","img":"Korok002.jpg"},{"id":"Seed003","no":3,"hint_en":"Complete the block puzzle.","hint_cn":"完成方块拼图","img":"Korok003.jpg"},{"id":"Seed004","no":4,"hint_en":"Start at the south side of the river, and follow the flowers.","hint_cn":"从河南岸出发，跟随花朵","img":"Korok004.jpg"},{"id":"Seed005","no":5,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok005.jpg"},{"id":"Seed006","no":6,"hint_en":"Push the boulder into the nearby large hole.","hint_cn":"把巨石推进附近的大坑","img":"Korok006.jpg"},{"id":"Seed007","no":7,"hint_en":"Follow the flower trail which starts at the bottom of the hollow log pieces.","hint_cn":"跟随空心原木底部开始的花径","img":"Korok007.jpg"},{"id":"Seed008","no":8,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok008.jpg"},{"id":"Seed009","no":9,"hint_en":"Pick up the rock at the top of the rock structure.","hint_cn":"捡起石堆顶部的石头","img":"Korok009.jpg"},{"id":"Seed010","no":10,"hint_en":"Interact with the fairy lights under the bridge. Use Magnesis to make a safe platform.","hint_cn":"与桥下的精灵光点互动，用磁力制做安全平台","img":"Korok010.jpg"},{"id":"Seed011","no":11,"hint_en":"Pick up the solitary rock at the peak of the shorter Dueling Peak.","hint_cn":"捡起双丘矮峰顶上的孤立石头","img":"Korok011.jpg"},{"id":"Seed012","no":12,"hint_en":"Melt the block of ice, then examine the fairy lights.","hint_cn":"融化冰块，然后查看精灵光点","img":"Korok012.jpg"},{"id":"Seed013","no":13,"hint_en":"Use the nearby rock to complete the circle.","hint_cn":"用附近的石头补全圆圈","img":"Korok013.jpg"},{"id":"Seed014","no":14,"hint_en":"Use Magnesis to place the metal block to match the nearby set.","hint_cn":"用磁力移动金属方块匹配附近组合","img":"Korok014.jpg"},{"id":"Seed015","no":15,"hint_en":"Interact with the fairy lights. You must have left the Great Plateau to obtain this seed. This is above the pool you awaken from within the Shrine of Resurrection.","hint_cn":"与精灵光点互动。必须离开初始台地才能获得此种子。位于复苏神庙醒来的水池上方","img":"Korok015.jpg"},{"id":"Seed016","no":16,"hint_en":"Pick up this rock.","hint_cn":"捡起这块石头","img":"Korok016.jpg"},{"id":"Seed017","no":17,"hint_en":"Go to the edge of the cliff (behind the wall) to find the large slab. Move it using Stasis, then pick up the smaller rock under it.","hint_cn":"走到悬崖边（墙后）找大石板。用静止器移动它，然后捡起下面的小石头","img":"Korok017.jpg"},{"id":"Seed018","no":18,"hint_en":"Examine the fairy lights at the top of the Temple of Time.","hint_cn":"查看时之神殿顶部的精灵光点","img":"Korok018.jpg"},{"id":"Seed019","no":19,"hint_en":"Examine the fairy lights on the top of the Woodcutter's Cabin.","hint_cn":"查看伐木小屋顶部的精灵光点","img":"Korok019.jpg"},{"id":"Seed020","no":20,"hint_en":"Use Magnesis to lift the metal door, then lift the rock hidden underneath. This seed is found at the very base of the Great Plateau, so it won't be available until the Paraglider is obtained.","hint_cn":"用磁力抬起金属门，然后举起下面隐藏的石头。必须获得滑翔伞后才能找到","img":"Korok020.jpg"},{"id":"Seed021","no":21,"hint_en":"Use Magnesis to lift the metal door, then lift the rock hidden underneath.","hint_cn":"用磁力抬起金属门，然后举起下面隐藏的石头","img":"Korok021.jpg"},{"id":"Seed022","no":22,"hint_en":"Clear the leaves, then pick up the rock.","hint_cn":"清理树叶，然后捡起石头","img":"Korok022.jpg"},{"id":"Seed023","no":23,"hint_en":"Follow the flower trail through the giant hollow log.","hint_cn":"跟随穿过巨大空心原木的花径","img":"Korok023.jpg"},{"id":"Seed024","no":24,"hint_en":"Use Magnesis to lift the ball on the chain into the hole of the tree trunk.","hint_cn":"用磁力把链球抬进树洞","img":"Korok024.jpg"},{"id":"Seed025","no":25,"hint_en":"Lift the rock found underneath two larger rocks.","hint_cn":"举起两块大石头下面的石头","img":"Korok025.jpg"},{"id":"Seed026","no":26,"hint_en":"Use Magnesis to put the block in the correct place. Located on a cliff ledge.","hint_cn":"用磁力把方块放到正确位置。位于悬崖壁架上","img":"Korok026.jpg"},{"id":"Seed027","no":27,"hint_en":"Place a palm fruit in the empty basket.","hint_cn":"把椰子放进空篮子","img":"Korok027.jpg"},{"id":"Seed028","no":28,"hint_en":"Place an apple in the empty basket.","hint_cn":"把苹果放进空篮子","img":"Korok028.jpg"},{"id":"Seed029","no":29,"hint_en":"Blow up the boulders and pick up the rock underneath.","hint_cn":"炸碎巨石，捡起下面的石头","img":"Korok029.jpg"},{"id":"Seed030","no":30,"hint_en":"Climb to the top of the hill and lift up the solitary rock. Level 1 cold resistance recommended.","hint_cn":"爬到山顶举起孤立的石头。建议耐寒等级1","img":"Korok030.jpg"},{"id":"Seed031","no":31,"hint_en":"Grab a rock from the plateau to the northeast, and get it up to and complete the rock circle. You can jump up onto the platform from the southwestern edge.","hint_cn":"从东北高原搬一块石头上来补全石圈。可以从西南边缘跳上平台","img":"Korok031.jpg"},{"id":"Seed032","no":32,"hint_en":"Use Magnesis to lift the ball-and-chain and put it into the hollow stump.","hint_cn":"用磁力抬起链球放进空心树桩","img":"Korok032.jpg"},{"id":"Seed033","no":33,"hint_en":"Melt the ice and examine the fairy lights.","hint_cn":"融化冰块查看精灵光点","img":"Korok033.jpg"},{"id":"Seed034","no":34,"hint_en":"Climb to the top of the hill and lift the small rock.","hint_cn":"爬到山顶举起小石头","img":"Korok034.jpg"},{"id":"Seed035","no":35,"hint_en":"Shoot the balloons.","hint_cn":"射气球","img":"Korok035.jpg"},{"id":"Seed036","no":36,"hint_en":"Lift the rock in the tree.","hint_cn":"举起树上的石头","img":"Korok036.jpg"},{"id":"Seed037","no":37,"hint_en":"Stand on the stump, and shoot the flying acorns.","hint_cn":"站在树桩上，射飞起来的橡果","img":"Korok037.jpg"},{"id":"Seed038","no":38,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok038.jpg"},{"id":"Seed039","no":39,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok039.jpg"},{"id":"Seed040","no":40,"hint_en":"Climb to the top of the flag pole, then examine the fairy lights.","hint_cn":"爬到旗杆顶，查看精灵光点","img":"Korok040.jpg"},{"id":"Seed041","no":41,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok041.jpg"},{"id":"Seed042","no":42,"hint_en":"Start between the three large cliffs to the northwest, and follow the flowers.","hint_cn":"从西北三大悬崖之间出发，跟随花朵","img":"Korok042.jpg"},{"id":"Seed043","no":43,"hint_en":"Throw a rock into the circle of rocks. This seed belongs to the Great Plateau Tower Region, but won't be available until the Paraglider is obtained.","hint_cn":"把石头扔进石圈。必须获得滑翔伞后才能找到","img":"Korok043.jpg"},{"id":"Seed044","no":44,"hint_en":"In the 'spout' of the fish statue on top of Zora's Domain, examine the fairy lights.","hint_cn":"在卓拉领地顶部鱼雕像的'喷水口'处查看精灵光点","img":"Korok044.jpg"},{"id":"Seed045","no":45,"hint_en":"Place an apple in the empty offering bowl.","hint_cn":"把苹果放进空供碗","img":"Korok045.jpg"},{"id":"Seed046","no":46,"hint_en":"Start on top of the rock bridge and chase the flower trail by climbing down and around under the bridge.","hint_cn":"从石桥顶出发，沿桥下绕一圈追花径","img":"Korok046.jpg"},{"id":"Seed047","no":47,"hint_en":"Burn or cut away the dead leaves and then lift up the small rock.","hint_cn":"烧掉或砍掉枯叶，然后举起小石头","img":"Korok047.jpg"},{"id":"Seed048","no":48,"hint_en":"Place apple.","hint_cn":"放苹果","img":"Korok048.jpg"},{"id":"Seed049","no":49,"hint_en":"Burn the leaves and pick up the revealed rock.","hint_cn":"烧掉树叶，捡起露出的石头","img":"Korok049.jpg"},{"id":"Seed050","no":50,"hint_en":"Place an apple in the empty basket.","hint_cn":"把苹果放进空篮子","img":"Korok050.jpg"},{"id":"Seed051","no":51,"hint_en":"Push the boulder off the small tower into the indented hole below.","hint_cn":"把巨石从小塔上推到下方的凹槽里","img":"Korok051.jpg"},{"id":"Seed052","no":52,"hint_en":"Lift the rock up.","hint_cn":"举起石头","img":"Korok052.jpg"},{"id":"Seed053","no":53,"hint_en":"Examine the swirling leaves at the top of the Tech Lab.","hint_cn":"查看技术实验室顶部旋转的树叶","img":"Korok053.jpg"},{"id":"Seed054","no":54,"hint_en":"Stand near the pinwheel and shoot the balloons. The third balloon is behind you, hidden in the log.","hint_cn":"站在风车旁射气球。第三个气球在你身后藏在原木里","img":"Korok054.jpg"},{"id":"Seed055","no":55,"hint_en":"Pick up the rock in the stump.","hint_cn":"捡起树桩里的石头","img":"Korok055.jpg"},{"id":"Seed056","no":56,"hint_en":"Climb atop the guardian found at the top of the Hateno Ancient Tech Lab. The easiest place to climb up is the broken guardian's leg.","hint_cn":"爬上哈特诺古代研究所顶部的守护者。从断腿处爬最容易","img":"Korok056.jpg"},{"id":"Seed057","no":57,"hint_en":"Stand near the pinwheel and shoot all five balloon targets.","hint_cn":"站在风车旁射五个气球靶","img":"Korok057.jpg"},{"id":"Seed058","no":58,"hint_en":"Pick up the metal cube and place it back into its correct spot.","hint_cn":"捡起金属方块放回正确位置","img":"Korok058.jpg"},{"id":"Seed059","no":59,"hint_en":"Follow the long yellow flower trail to the top of the hill. The start of the trail is pictured here and begins a bit north west of the location on the ground around the hill.","hint_cn":"跟随长长的黄色花径到山顶。花径起点在图中位置，在山周围地面上稍西北","img":"Korok059.jpg"},{"id":"Seed060","no":60,"hint_en":"Stand next to the pinwheel and shoot the three balloon targets.","hint_cn":"站在风车旁射三个气球靶","img":"Korok060.jpg"},{"id":"Seed061","no":61,"hint_en":"Climb on top of the stone wall and stand next to the pinwheel. Two acorns will fly above the treetops. Carefully aim and destroy them with arrows. You can use Stasis on the acorns to help you.","hint_cn":"爬上石墙站在风车旁。两个橡果会从树梢上方飞过。小心瞄准射箭。可以用静止器","img":"Korok061.jpg"},{"id":"Seed062","no":62,"hint_en":"Jump or dive into the ring of flowers in the water below the cliff.","hint_cn":"从悬崖跳下或跳入下方水中的花圈","img":"Korok062.jpg"},{"id":"Seed063","no":63,"hint_en":"From the bridge above, put a Cryonis pillar just in front of the circle of rocks, then toss a rock onto the pillar so it bounces into the circle.","hint_cn":"从桥上在石圈正前方造冰柱，然后把石头扔到冰柱上弹进圈里","img":"Korok063.jpg"},{"id":"Seed064","no":64,"hint_en":"Light the two torches up here.","hint_cn":"点燃这里的两个火炬","img":"Korok064.jpg"},{"id":"Seed065","no":65,"hint_en":"Jump or dive into the ring of flowers. You can glide from the top of the Hylia bridge or use a cryonis pillar.","hint_cn":"跳下或跳入花圈。可以从海拉鲁桥顶滑翔或造冰柱","img":"Korok065.jpg"},{"id":"Seed066","no":66,"hint_en":"Move the metal block to match both sets identically.","hint_cn":"移动金属方块使两组图案完全相同","img":"Korok066.jpg"},{"id":"Seed067","no":67,"hint_en":"Throw a boulder into the ring of rocks in the river.","hint_cn":"把巨石扔进河里的石圈","img":"Korok067.jpg"},{"id":"Seed068","no":68,"hint_en":"Lift the rock found at the top of Mount Floria.","hint_cn":"举起弗罗里亚山顶的石头","img":"Korok068.jpg"},{"id":"Seed069","no":69,"hint_en":"Drop an apple into the empty offering bowl.","hint_cn":"把苹果丢进空供碗","img":"Korok069.jpg"},{"id":"Seed070","no":70,"hint_en":"Swim to the small island in the lake and lift the small rock on top.","hint_cn":"游到湖中小岛，举起顶上的小石头","img":"Korok070.jpg"},{"id":"Seed071","no":71,"hint_en":"Pick up this rock.","hint_cn":"捡起这块石头","img":"Korok071.jpg"},{"id":"Seed072","no":72,"hint_en":"Investigate behind the two statues.","hint_cn":"在两座雕像后面调查","img":"Korok072.jpg"},{"id":"Seed073","no":73,"hint_en":"Examine the fairy lights at the top of the fountain.","hint_cn":"查看喷泉顶部的精灵光点","img":"Korok073.jpg"},{"id":"Seed074","no":74,"hint_en":"Examine the fairy lights at the top of the spire.","hint_cn":"查看尖塔顶部的精灵光点","img":"Korok074.jpg"},{"id":"Seed075","no":75,"hint_en":"Climb to the very top of the waterfall pillar and examine the fairy lights.","hint_cn":"爬到瀑布柱最顶端查看精灵光点","img":"Korok075.jpg"},{"id":"Seed076","no":76,"hint_en":"Solve the Magnesis block puzzle. The block is above the pavilion.","hint_cn":"解开磁力方块拼图。方块在亭子上方","img":"Korok076.jpg"},{"id":"Seed077","no":77,"hint_en":"Solve the Magnesis block puzzle. The block is on the wooden platform above.","hint_cn":"解开磁力方块拼图。方块在上方木平台上","img":"Korok077.jpg"},{"id":"Seed078","no":78,"hint_en":"There are two fairy lights dancing around here. Catch them both for two seeds.","hint_cn":"这里有两个精灵光点在飞舞。两个都抓可得两个种子","img":"Korok078.jpg"},{"id":"Seed079","no":79,"hint_en":"Melt the block of ice. Cold Resistance Level 2 recommended.","hint_cn":"融化冰块。建议耐寒等级2","img":"Korok079.jpg"},{"id":"Seed080","no":80,"hint_en":"Melt the block of ice. Cold Resistance Level 2 recommended.","hint_cn":"融化冰块。建议耐寒等级2","img":"Korok080.jpg"},{"id":"Seed081","no":81,"hint_en":"Stand next to the pinwheel, shoot the three acorns. You can use stasis to make it easier.","hint_cn":"站在风车旁射三个橡果。可以用静止器辅助","img":"Korok081.jpg"},{"id":"Seed082","no":82,"hint_en":"Catch the fairy lights circling the area.","hint_cn":"抓住绕区域盘旋的精灵光点","img":"Korok082.jpg"},{"id":"Seed083","no":83,"hint_en":"On the cliffside there are some metal cubes. Put the missing cube back into the correct spot to make everything match.","hint_cn":"悬崖边有金属方块。把缺失的方块放回正确位置使一切匹配","img":"Korok083.jpg"},{"id":"Seed084","no":84,"hint_en":"The flower trail to this seed starts to the south, on the eastern cliff face. Follow the flowers to the seed.","hint_cn":"这个种子的花径从南边东面崖壁开始。跟随花朵找种子","img":"Korok084.jpg"},{"id":"Seed085","no":85,"hint_en":"This race platform starts far to the southeast, on the peak above the Ka'o Makagh Shrine. Race to the ring for the seed.","hint_cn":"这个赛跑起点平台在东南远处，卡奥·玛卡神庙上方峰顶。赛跑至圆环","img":"Korok085.jpg"},{"id":"Seed086","no":86,"hint_en":"Stand near the pinwheel and shoot the five balloons circling overhead.","hint_cn":"站在风车旁射头顶盘旋的五个气球","img":"Korok086.jpg"},{"id":"Seed087","no":87,"hint_en":"There are two ruins side by side. The one to the north has an extra rock, the one to the south is missing a rock. Carry the extra to the missing spot for the seed.","hint_cn":"两座遗迹并排。北边多一块石头，南边缺一块。把多余的搬到缺失处","img":"Korok087.jpg"},{"id":"Seed088","no":88,"hint_en":"Use the rock to complete the circle.","hint_cn":"用石头补全圆圈","img":"Korok088.jpg"},{"id":"Seed089","no":89,"hint_en":"The flower trail for this begins as you reach the island.","hint_cn":"到达小岛时花径就开始","img":"Korok089.jpg"},{"id":"Seed090","no":90,"hint_en":"Stand on the seed platform at the nearby shrine. Within the timer, reach the tiny island east of there.","hint_cn":"站在附近神庙的种子平台上。限时到达东边小岛","img":"Korok090.jpg"},{"id":"Seed091","no":91,"hint_en":"Throw a small rock into the ring of rocks found in the water. Cryonis can make it easier to reach.","hint_cn":"把小石头扔进水里的石圈。造冰柱可以更容易到达","img":"Korok091.jpg"},{"id":"Seed092","no":92,"hint_en":"Lift up the small rock found at the edge of the creek.","hint_cn":"举起溪边的小石头","img":"Korok092.jpg"},{"id":"Seed093","no":93,"hint_en":"In a cave in this hill, count to 5 using the flowers.","hint_cn":"在这个山洞里，按花数数到5","img":"Korok093.jpg"},{"id":"Seed094","no":94,"hint_en":"Complete the circle of rocks using three nearby rocks.","hint_cn":"用附近三块石头补全石圈","img":"Korok094.jpg"},{"id":"Seed095","no":95,"hint_en":"Push the boulder so it rolls into the hole.","hint_cn":"推巨石使其滚进坑里","img":"Korok095.jpg"},{"id":"Seed096","no":96,"hint_en":"Pick up this rock.","hint_cn":"捡起这块石头","img":"Korok096.jpg"},{"id":"Seed097","no":97,"hint_en":"Catch the fairy lights that run around the ruins.","hint_cn":"抓住绕遗迹跑的精灵光点","img":"Korok097.jpg"},{"id":"Seed098","no":98,"hint_en":"Look under the bridge, and pick up the rock.","hint_cn":"看桥下，捡起石头","img":"Korok098.jpg"},{"id":"Seed099","no":99,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok099.jpg"},{"id":"Seed100","no":100,"hint_en":"Climb the flag pole, then examine the fairy lights.","hint_cn":"爬旗杆，查看精灵光点","img":"Korok100.jpg"},{"id":"Seed101","no":101,"hint_en":"Climb to the top of the stone pillar northwest of here to find the seed platform. Glide to the ring before the time runs out.","hint_cn":"爬到西北石柱顶找种子平台。滑翔到圆环别超时","img":"Korok101.jpg"},{"id":"Seed102","no":102,"hint_en":"Remove the big boulder and then lift the smaller rock.","hint_cn":"移开大巨石，然后举起小石头","img":"Korok102.jpg"},{"id":"Seed103","no":103,"hint_en":"Under the bridge, shoot the hanging acorn.","hint_cn":"在桥下射悬挂的橡果","img":"Korok103.jpg"},{"id":"Seed104","no":104,"hint_en":"Put the magnetic rock in the well.","hint_cn":"把磁力石头放进井里","img":"Korok104.jpg"},{"id":"Seed105","no":105,"hint_en":"Stand on the stump and look at the large tree behind it. You will see two targets being tossed up behind the tree. Aim carefully and you can hit them with arrows.","hint_cn":"站在树桩上看它后面的大树。会看到两个靶子在树后抛起。小心瞄准射箭","img":"Korok105.jpg"},{"id":"Seed106","no":106,"hint_en":"At the top of the hill to the west, roll the boulder down into the hole.","hint_cn":"在西山顶上，把巨石滚进坑里","img":"Korok106.jpg"},{"id":"Seed107","no":107,"hint_en":"Blow up the boulders and pick up the rock under them.","hint_cn":"炸碎巨石，捡起下面的石头","img":"Korok107.jpg"},{"id":"Seed108","no":108,"hint_en":"Jump all three fences in a row. This can also be done with the Master Cycle Zero using the Zero Jump.","hint_cn":"连续跳三个栅栏。也可以用摩托 zero jump","img":"Korok108.jpg"},{"id":"Seed109","no":109,"hint_en":"Follow the flower trail in a little circle around the area.","hint_cn":"跟随绕区域一圈的花径","img":"Korok109.jpg"},{"id":"Seed110","no":110,"hint_en":"Stand on the stump and shoot the three balloons.","hint_cn":"站在树桩上射三个气球","img":"Korok110.jpg"},{"id":"Seed111","no":111,"hint_en":"Lift the rock on top of the rock formation.","hint_cn":"举起岩顶上的石头","img":"Korok111.jpg"},{"id":"Seed112","no":112,"hint_en":"Jump into lilies.","hint_cn":"跳进睡莲","img":"Korok112.jpg"},{"id":"Seed113","no":113,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok113.jpg"},{"id":"Seed114","no":114,"hint_en":"Shoot the acorn in the log.","hint_cn":"射原木里的橡果","img":"Korok114.jpg"},{"id":"Seed115","no":115,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok115.jpg"},{"id":"Seed116","no":116,"hint_en":"Pick up the rock on the top floor of the Coliseum.","hint_cn":"捡起斗技场顶层的石头","img":"Korok116.jpg"},{"id":"Seed117","no":117,"hint_en":"Chase the fairy lights and examine them.","hint_cn":"追精灵光点并查看","img":"Korok117.jpg"},{"id":"Seed118","no":118,"hint_en":"Race from the tree surrounded by Malice goo and climb up to the rock point.","hint_cn":"从被瘴气包围的树开始赛跑，爬到岩石点","img":"Korok118.jpg"},{"id":"Seed119","no":119,"hint_en":"Shoot the acorn hanging under the bridge.","hint_cn":"射桥下悬挂的橡果","img":"Korok119.jpg"},{"id":"Seed120","no":120,"hint_en":"Hidden underneath the small rock near the palm tree.","hint_cn":"藏在棕榈树旁小石头下","img":"Korok120.jpg"},{"id":"Seed121","no":121,"hint_en":"Halfway down the cliff there is a tiny ledge with a rock. Pick it up.","hint_cn":"悬崖半腰有个小石架带块石头。捡起","img":"Korok121.jpg"},{"id":"Seed122","no":122,"hint_en":"Solve the cube puzzle.","hint_cn":"解开方块拼图","img":"Korok122.jpg"},{"id":"Seed123","no":123,"hint_en":"Complete the rock circle.","hint_cn":"完成石圈","img":"Korok123.jpg"},{"id":"Seed124","no":124,"hint_en":"Throw a rock into the circle. You may have to slide the rock over a cryonis block.","hint_cn":"把石头扔进圆圈。可能需要在冰柱上滑过去","img":"Korok124.jpg"},{"id":"Seed125","no":125,"hint_en":"Throw a rock into the circle of rocks. Use Cryonis to help cover the distance.","hint_cn":"把石头扔进石圈。用造冰术帮助够距离","img":"Korok125.jpg"},{"id":"Seed126","no":126,"hint_en":"Put the ball into the stump.","hint_cn":"把球放进树桩","img":"Korok126.jpg"},{"id":"Seed127","no":127,"hint_en":"Shoot the acorn.","hint_cn":"射橡果","img":"Korok127.jpg"},{"id":"Seed128","no":128,"hint_en":"Pick up the rock in the dried up well.","hint_cn":"捡起干涸井里的石头","img":"Korok128.jpg"},{"id":"Seed129","no":129,"hint_en":"Dive into the circle of lilies.","hint_cn":"跳入睡莲圈","img":"Korok129.jpg"},{"id":"Seed130","no":130,"hint_en":"Solve the cube puzzle. The cube is in the water.","hint_cn":"解开方块拼图。方块在水里","img":"Korok130.jpg"},{"id":"Seed131","no":131,"hint_en":"Pick up the rock on a standalone wall.","hint_cn":"捡起独立墙上的石头","img":"Korok131.jpg"},{"id":"Seed132","no":132,"hint_en":"Follow the flower trail that starts on a stump to the northeast.","hint_cn":"跟随东北树桩开始的花径","img":"Korok132.jpg"},{"id":"Seed133","no":133,"hint_en":"Put the metal rock in the hole in the stump.","hint_cn":"把金属石头放进树桩的洞里","img":"Korok133.jpg"},{"id":"Seed134","no":134,"hint_en":"Climb the thick tree, and pick up the rock on top.","hint_cn":"爬大树，捡起顶上的石头","img":"Korok134.jpg"},{"id":"Seed135","no":135,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok135.jpg"},{"id":"Seed136","no":136,"hint_en":"Drop an apple into the empty offering bowl.","hint_cn":"把苹果丢进空供碗","img":"Korok136.jpg"},{"id":"Seed137","no":137,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok137.jpg"},{"id":"Seed138","no":138,"hint_en":"Lift the stone.","hint_cn":"举起石头","img":"Korok138.jpg"},{"id":"Seed139","no":139,"hint_en":"Move the large slab, then lift the small rock underneath.","hint_cn":"移动大石板，然后举起下面的小石头","img":"Korok139.jpg"},{"id":"Seed140","no":140,"hint_en":"Complete the circle with a rock found on the same cliffside.","hint_cn":"用同崖壁上的石头补全圆圈","img":"Korok140.jpg"},{"id":"Seed141","no":141,"hint_en":"Inside of a cave behind a bombable wall, lift the rock.","hint_cn":"在可炸墙后的山洞里举起石头","img":"Korok141.jpg"},{"id":"Seed142","no":142,"hint_en":"Climb to the top of this mountain and lift up the small rock.","hint_cn":"爬到山顶举起小石头","img":"Korok142.jpg"},{"id":"Seed143","no":143,"hint_en":"Remove apples from the tree on the left until it looks like the two on the right.","hint_cn":"从左边树上摘掉苹果使其和右边两棵一样","img":"Korok143.jpg"},{"id":"Seed144","no":144,"hint_en":"Lift the small rock at the top of the peak. Cold Resistance Level 1 recommended.","hint_cn":"举起峰顶小石头。建议耐寒等级1","img":"Korok144.jpg"},{"id":"Seed145","no":145,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok145.jpg"},{"id":"Seed146","no":146,"hint_en":"Lift the rock on the small island at the center of the poisonous bog.","hint_cn":"举起毒沼中央小岛上的石头","img":"Korok146.jpg"},{"id":"Seed147","no":147,"hint_en":"Offer a Hearty Durian.","hint_cn":"供奉一颗榴莲","img":"Korok147.jpg"},{"id":"Seed148","no":148,"hint_en":"Throw a rock into the center of the protruding rocks.","hint_cn":"把石头扔进突出岩石的中心","img":"Korok148.jpg"},{"id":"Seed149","no":149,"hint_en":"Shoot the balloon that's underneath the bridge.","hint_cn":"射桥下的气球","img":"Korok149.jpg"},{"id":"Seed150","no":150,"hint_en":"Blow up the rock pile and pick up the rock underneath.","hint_cn":"炸碎石堆，捡起下面的石头","img":"Korok150.jpg"},{"id":"Seed151","no":151,"hint_en":"Use Magnesis to grab the iron cube from the block puzzle on the east hand of the statue and take it to the west hand.","hint_cn":"用磁力从雕像右手的方块拼图抓铁块搬到左手","img":"Korok151.jpg"},{"id":"Seed152","no":152,"hint_en":"Visit each group of flowers in order, 1 through 5.","hint_cn":"按顺序1到5访问每组花","img":"Korok152.jpg"},{"id":"Seed153","no":153,"hint_en":"Shoot the balloon.","hint_cn":"射气球","img":"Korok153.jpg"},{"id":"Seed154","no":154,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok154.jpg"},{"id":"Seed155","no":155,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok155.jpg"},{"id":"Seed156","no":156,"hint_en":"Complete the rock spiral.","hint_cn":"完成石螺旋","img":"Korok156.jpg"},{"id":"Seed157","no":157,"hint_en":"Bomb the wall and pick up the rock.","hint_cn":"炸墙捡起石头","img":"Korok157.jpg"},{"id":"Seed158","no":158,"hint_en":"Complete the rock circle. The rock is in the direction of the gap in the circle, to the north.","hint_cn":"完成石圈。石头在圆圈缺口方向（北）","img":"Korok158.jpg"},{"id":"Seed159","no":159,"hint_en":"Grab the boulder at the center of the rock ring west of here, and place it in the empty spot.","hint_cn":"从西边石圈中心搬巨石，放到空位","img":"Korok159.jpg"},{"id":"Seed160","no":160,"hint_en":"Stand on the edge of the bridge at the north end. Toss a boulder down into the ring of rocks in the water below.","hint_cn":"站在北端桥边。把巨石扔下水中石圈","img":"Korok160.jpg"},{"id":"Seed161","no":161,"hint_en":"Stand on the seed platform at the base of the waterfall, then swim up the waterfall using Zora Armor.","hint_cn":"站在瀑布底的种子平台上，穿卓拉铠甲游上瀑布","img":"Korok161.jpg"},{"id":"Seed162","no":162,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok162.jpg"},{"id":"Seed163","no":163,"hint_en":"Put a boulder on each of the three islands here. The boulders are magnetic, but two of them are chained together. Use Stasis to hold one of the chained boulders in place while you place the other.","hint_cn":"在三座小岛上各放一块巨石。巨石带磁力，其中两块链在一起。用静止器固定链上一块再放另一块","img":"Korok163.jpg"},{"id":"Seed164","no":164,"hint_en":"Remove fruit from the tree with too many to make it match.","hint_cn":"从果实过多的仙人掌上摘果使其匹配","img":"Korok164.jpg"},{"id":"Seed165","no":165,"hint_en":"Toss a boulder into the circle of rocks found in the lake.","hint_cn":"把巨石扔进湖里的石圈","img":"Korok165.jpg"},{"id":"Seed166","no":166,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok166.jpg"},{"id":"Seed167","no":167,"hint_en":"Use Magnesis to solve the block puzzle.","hint_cn":"用磁力解开方块拼图","img":"Korok167.jpg"},{"id":"Seed168","no":168,"hint_en":"Grab fruit from the cactus with extra until they match.","hint_cn":"从果实过多的仙人掌上摘果使其匹配","img":"Korok168.jpg"},{"id":"Seed169","no":169,"hint_en":"","hint_cn":"","img":"Korok169.jpg"},{"id":"Seed170","no":170,"hint_en":"Climb to the highest point on the skeleton.","hint_cn":"爬到骷髅最高处","img":"Korok170.jpg"},{"id":"Seed171","no":171,"hint_en":"Pick up the rock on top of the pillar.","hint_cn":"捡起柱子顶上的石头","img":"Korok171.jpg"},{"id":"Seed172","no":172,"hint_en":"The seed platform for this race is on the arch to the northwest.","hint_cn":"这个赛跑的种子平台在西北拱门上","img":"Korok172.jpg"},{"id":"Seed173","no":173,"hint_en":"Complete the rock circle.","hint_cn":"完成石圈","img":"Korok173.jpg"},{"id":"Seed174","no":174,"hint_en":"Remove fruit from the cactus with extra until it matches.","hint_cn":"从果实过多的仙人掌上摘果使其匹配","img":"Korok174.jpg"},{"id":"Seed175","no":175,"hint_en":"Solve the Magnesis block puzzle inside the skull rock. The cube to use is on the ceiling.","hint_cn":"在骷髅头岩石里解开磁力方块拼图。要用的方块在天花板上","img":"Korok175.jpg"},{"id":"Seed176","no":176,"hint_en":"Solve the Magnesis block puzzle. If you're having trouble putting the block in, try lining a corner up with the hole in the puzzle.","hint_cn":"解开磁力方块拼图。放不进去试试把角对准洞里的孔","img":"Korok176.jpg"},{"id":"Seed177","no":177,"hint_en":"At the very top of the statue.","hint_cn":"在雕像最顶端","img":"Korok177.jpg"},{"id":"Seed178","no":178,"hint_en":"Shoot the balloon in between the statue's wrists.","hint_cn":"射雕像双腕之间的气球","img":"Korok178.jpg"},{"id":"Seed179","no":179,"hint_en":"Pick up the rock on top of the pillar.","hint_cn":"捡起柱子顶上的石头","img":"Korok179.jpg"},{"id":"Seed180","no":180,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok180.jpg"},{"id":"Seed181","no":181,"hint_en":"Shoot the balloons while standing near the pinwheel.","hint_cn":"站在风车旁射气球","img":"Korok181.jpg"},{"id":"Seed182","no":182,"hint_en":"Solve the large Magnesis Block puzzle.","hint_cn":"解开大型磁力方块拼图","img":"Korok182.jpg"},{"id":"Seed183","no":183,"hint_en":"Not counting the rock in the middle, two of these lines have only 8 rocks in them. Put the 2 extra rocks at the east and southwest arms to finish the pattern.","hint_cn":"不算中间的石头，这两条线只有8块。把多余2块放到东西两侧补全图案","img":"Korok183.jpg"},{"id":"Seed184","no":184,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok184.jpg"},{"id":"Seed185","no":185,"hint_en":"Bomb the rocks and pick up the one underneath.","hint_cn":"炸碎石块捡起下面的","img":"Korok185.jpg"},{"id":"Seed186","no":186,"hint_en":"Complete the rock pattern.","hint_cn":"完成石头图案","img":"Korok186.jpg"},{"id":"Seed187","no":187,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok187.jpg"},{"id":"Seed188","no":188,"hint_en":"Climb the pillar and pick up the rock.","hint_cn":"爬柱子捡起石头","img":"Korok188.jpg"},{"id":"Seed189","no":189,"hint_en":"Lift the rock at the center of the promenade.","hint_cn":"举起步道中心的石头","img":"Korok189.jpg"},{"id":"Seed190","no":190,"hint_en":"Jump or dive into the ring of flowers.","hint_cn":"跳下或跳入花圈","img":"Korok190.jpg"},{"id":"Seed191","no":191,"hint_en":"Jump or dive into the ring of flowers.","hint_cn":"跳下或跳入花圈","img":"Korok191.jpg"},{"id":"Seed192","no":192,"hint_en":"Roll a large boulder into the hole. The Stasis rune may help if the boulder misses the mark.","hint_cn":"把巨石滚进坑里。偏了用静止器辅助","img":"Korok192.jpg"},{"id":"Seed193","no":193,"hint_en":"Lift the big rock (using Stasis or an Octo Balloon), and then pick up the small rock under it.","hint_cn":"举起大石头（用静止器或气球），然后捡起下面的小石头","img":"Korok193.jpg"},{"id":"Seed194","no":194,"hint_en":"Stand near the pinwheel and shoot down all three balloon targets.","hint_cn":"站在风车旁射下三个气球靶","img":"Korok194.jpg"},{"id":"Seed195","no":195,"hint_en":"Pick up the rock found underneath the bridge.","hint_cn":"捡起桥下的石头","img":"Korok195.jpg"},{"id":"Seed196","no":196,"hint_en":"Fill in all three missing spots in the ring of rocks.","hint_cn":"补全石圈三处缺失","img":"Korok196.jpg"},{"id":"Seed197","no":197,"hint_en":"At water level, in the cave, drop an apple into the offering bowl.","hint_cn":"在水位线的山洞里，把苹果丢进供碗","img":"Korok197.jpg"},{"id":"Seed198","no":198,"hint_en":"Follow the yellow flower trail up the hill.","hint_cn":"沿黄色花径上山","img":"Korok198.jpg"},{"id":"Seed199","no":199,"hint_en":"Jump into the circle of lilies.","hint_cn":"跳入睡莲圈","img":"Korok199.jpg"},{"id":"Seed200","no":200,"hint_en":"Climb up to this ledge, and lift the rock.","hint_cn":"爬上这个壁架，举起石头","img":"Korok200.jpg"},{"id":"Seed201","no":201,"hint_en":"Shoot this emblem.","hint_cn":"射这个纹章","img":"Korok201.jpg"},{"id":"Seed202","no":202,"hint_en":"Shoot this emblem.","hint_cn":"射这个纹章","img":"Korok202.jpg"},{"id":"Seed203","no":203,"hint_en":"On the upper ledge, lift this rock.","hint_cn":"在上方壁架举起这块石头","img":"Korok203.jpg"},{"id":"Seed204","no":204,"hint_en":"Climb up into the hollow top of the stone pillar and place an apple in the empty basket by the statue.","hint_cn":"爬上石柱空心顶，在雕像旁空篮子里放苹果","img":"Korok204.jpg"},{"id":"Seed205","no":205,"hint_en":"Shoot the balloon in the heart shaped opening next to vah medoh.","hint_cn":"射瓦·梅多旁边心形开口里的气球","img":"Korok205.jpg"},{"id":"Seed206","no":206,"hint_en":"Climb to the top of the tallest tree here.","hint_cn":"爬到这里最高的树顶","img":"Korok206.jpg"},{"id":"Seed207","no":207,"hint_en":"Climb to the top, and lift up the rock.","hint_cn":"爬到顶举起石头","img":"Korok207.jpg"},{"id":"Seed208","no":208,"hint_en":"Climb to the top, and lift up the rock.","hint_cn":"爬到顶举起石头","img":"Korok208.jpg"},{"id":"Seed209","no":209,"hint_en":"Two of these trees have only one apple, make the third look like them.","hint_cn":"两棵树只有一个苹果，让第三棵和它们一样","img":"Korok209.jpg"},{"id":"Seed210","no":210,"hint_en":"Geronimo.","hint_cn":"跳！","img":"Korok210.jpg"},{"id":"Seed211","no":211,"hint_en":"Climb up to the seed platform on the wood platform high above the chasm to the east, then race to the seed. The ring disappears quickly, so save before you attempt it. Speed boosts help, run off the platform, paraglide very little (gliding spends the most time while covering the least distance and height), then sprint to the circle.","hint_cn":"种子平台在东边深渊上方木平台上，然后赛跑取种子。圆环消失很快，建议先存档。加速辅助，跳下平台，少滑翔（滑翔费时最远），冲刺到圆环","img":"Korok211.jpg"},{"id":"Seed212","no":212,"hint_en":"Roll the boulder into the hole.","hint_cn":"把巨石滚进坑里","img":"Korok212.jpg"},{"id":"Seed213","no":213,"hint_en":"Climb to the top of Dueling Peaks Stable, then examine the fairy lights.","hint_cn":"爬到双马驿站顶，查看精灵光点","img":"Korok213.jpg"},{"id":"Seed214","no":214,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok214.jpg"},{"id":"Seed215","no":215,"hint_en":"Solve the simple block puzzle for the seed.","hint_cn":"解开简单方块拼图取种子","img":"Korok215.jpg"},{"id":"Seed216","no":216,"hint_en":"Stand near the pinwheel and shoot acorns that get thrown up above the nearby tree to the north.","hint_cn":"站在风车旁射北边附近树上方抛起的橡果","img":"Korok216.jpg"},{"id":"Seed217","no":217,"hint_en":"Pick up the rock here.","hint_cn":"捡起这里的石头","img":"Korok217.jpg"},{"id":"Seed218","no":218,"hint_en":"Climb up to this ledge, and lift this rock.","hint_cn":"爬上这个壁架，举起这块石头","img":"Korok218.jpg"},{"id":"Seed219","no":219,"hint_en":"Climb up the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok219.jpg"},{"id":"Seed220","no":220,"hint_en":"Roll a boulder through the two trees. Some boulders can be found uphill to the west.","hint_cn":"把巨石滚过两棵树。巨石可在西边坡上找到","img":"Korok220.jpg"},{"id":"Seed221","no":221,"hint_en":"Use Magnesis to move the iron cube into the correct spot.","hint_cn":"用磁力把铁块移到正确位置","img":"Korok221.jpg"},{"id":"Seed222","no":222,"hint_en":"Throw one of the many available rocks into the center of the circle. Use Cryonis Rune to help.","hint_cn":"把可用石头之一扔进圆圈中心。用造冰术辅助","img":"Korok222.jpg"},{"id":"Seed223","no":223,"hint_en":"Find the acorn in a hole in a tree and shoot it.","hint_cn":"在树洞找橡果射掉","img":"Korok223.jpg"},{"id":"Seed224","no":224,"hint_en":"Complete the star-shaped stone pattern with a nearby rock.","hint_cn":"用附近石头补全星形石图案","img":"Korok224.jpg"},{"id":"Seed225","no":225,"hint_en":"Roll this boulder away and then lift the uncovered rock.","hint_cn":"滚开这块巨石，然后举起露出的石头","img":"Korok225.jpg"},{"id":"Seed226","no":226,"hint_en":"Catch the fairy lights below the overhang.","hint_cn":"抓住悬垂下方的精灵光点","img":"Korok226.jpg"},{"id":"Seed227","no":227,"hint_en":"Half this block puzzle is underwater. Solve it.","hint_cn":"这个方块拼图一半在水下。解开它","img":"Korok227.jpg"},{"id":"Seed228","no":228,"hint_en":"Complete the block puzzle.","hint_cn":"完成方块拼图","img":"Korok228.jpg"},{"id":"Seed229","no":229,"hint_en":"Stand next to the pinwheel to trigger a balloon. A well timed bomb will make this balloon much easier than attempting to shoot it with arrows.","hint_cn":"站在风车旁触发气球。用定时炸弹比射箭更容易","img":"Korok229.jpg"},{"id":"Seed230","no":230,"hint_en":"The seed platform is on a ledge to the southeast. Race to the ring at the top of the enemy encampment.","hint_cn":"种子平台在东南壁架上。赛跑至敌营顶圆环","img":"Korok230.jpg"},{"id":"Seed231","no":231,"hint_en":"Offer an apple to the offering bowl that's missing one.","hint_cn":"给缺一个的供碗供奉苹果","img":"Korok231.jpg"},{"id":"Seed232","no":232,"hint_en":"The rock needed to complete this x-shaped puzzle is hidden in a nearby bush to the east. If you have a weapon that cuts grass/bushes, this will make it much easier to find.","hint_cn":"完成X形拼图所需的石头藏在东边附近灌木丛里。用斩草武器更容易找","img":"Korok232.jpg"},{"id":"Seed233","no":233,"hint_en":"Roll the boulder into the hole.","hint_cn":"把巨石滚进坑里","img":"Korok233.jpg"},{"id":"Seed234","no":234,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok234.jpg"},{"id":"Seed235","no":235,"hint_en":"Surrounding this rock are a square pattern of large metal cubes in the water . One is out of place. Use Cryonis to reach it, and Magnesis to move it into place.","hint_cn":"这块石头周围水里有方形金属块阵列。一块放错了。用造冰术到达，磁力移动归位","img":"Korok235.jpg"},{"id":"Seed236","no":236,"hint_en":"Pick up the rock at the ruins of the broken pillar.","hint_cn":"捡起断柱遗迹上的石头","img":"Korok236.jpg"},{"id":"Seed237","no":237,"hint_en":"Uphill to the southeast is a shield vendor who talks about shield surfing. This should be a hint. In the tree above him is the seed platform to start the race. Shield surf down to the marker for your seed.","hint_cn":"东南坡上有个盾滑商人。树上方是赛跑种子平台。盾滑到标记取种子","img":"Korok237.jpg"},{"id":"Seed238","no":238,"hint_en":"Follow the flower trail down the side of the broken pillar.","hint_cn":"跟随断柱边的花径","img":"Korok238.jpg"},{"id":"Seed239","no":239,"hint_en":"The seed platform is to the southwest next to a dead guardian. Race to the ring.","hint_cn":"种子平台在西南死守护者旁。赛跑至圆环","img":"Korok239.jpg"},{"id":"Seed240","no":240,"hint_en":"Shoot the acorn tucked inside this hollow log.","hint_cn":"射空心原木里的橡果","img":"Korok240.jpg"},{"id":"Seed241","no":241,"hint_en":"Follow the yellow flower trail. It begins on the hill just northwest of the end mark. Note that the final yellow flower before the end hides on the edge of the cliff.","hint_cn":"跟随黄色花径。起点在终点标记稍西北的小山上。注意终点前最后一朵黄花藏在悬崖边","img":"Korok241.jpg"},{"id":"Seed242","no":242,"hint_en":"Follow the flower trail that starts on the pillar to the west.","hint_cn":"跟随西边柱子开始的花径","img":"Korok242.jpg"},{"id":"Seed243","no":243,"hint_en":"There are three very large rock circles, with smaller circles of rocks within them. Take the stray rock from between the 3 large boulders in the southern huge circle, and put it in the middle of the smallest circle of rocks in the northern huge circle.","hint_cn":"三个大石圈里套小石圈。把南边大圈三块巨石间的散石放到北边大圈最小石圈中心","img":"Korok243.jpg"},{"id":"Seed244","no":244,"hint_en":"Lift the stone hidden behind the bombable rocks.","hint_cn":"举起可炸石后面隐藏的石头","img":"Korok244.jpg"},{"id":"Seed245","no":245,"hint_en":"Lift up the iron ball and put it into the well.","hint_cn":"举起铁球放进井里","img":"Korok245.jpg"},{"id":"Seed246","no":246,"hint_en":"Chase and catch the fairy lights circling the pond.","hint_cn":"追抓绕池塘盘旋的精灵光点","img":"Korok246.jpg"},{"id":"Seed247","no":247,"hint_en":"Solve the block puzzle. The block is downhill to the west.","hint_cn":"解开方块拼图。方块在西边坡下","img":"Korok247.jpg"},{"id":"Seed248","no":248,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok248.jpg"},{"id":"Seed249","no":249,"hint_en":"The seed platform for this race is on the larger plateau to the north.","hint_cn":"这个赛跑的种子平台在北边更大高原上","img":"Korok249.jpg"},{"id":"Seed250","no":250,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok250.jpg"},{"id":"Seed251","no":251,"hint_en":"Melt the ice.","hint_cn":"融化冰块","img":"Korok251.jpg"},{"id":"Seed252","no":252,"hint_en":"Follow the flower trail across the ribs.","hint_cn":"跟随穿过肋骨的花径","img":"Korok252.jpg"},{"id":"Seed253","no":253,"hint_en":"This flower trail goes back and forth to the various rocks in the area.","hint_cn":"这条花径来回绕区域内各岩石","img":"Korok253.jpg"},{"id":"Seed254","no":254,"hint_en":"One cactus has too many voltfruit. Make it look like the other two.","hint_cn":"一棵仙人掌电量果太多。让它和另外两棵一样","img":"Korok254.jpg"},{"id":"Seed255","no":255,"hint_en":"Follow the flower trail across the ribs.","hint_cn":"跟随穿过肋骨的花径","img":"Korok255.jpg"},{"id":"Seed256","no":256,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok256.jpg"},{"id":"Seed257","no":257,"hint_en":"Remove fruit from the cactus with extra until it matches.","hint_cn":"从果实过多的仙人掌上摘果使其匹配","img":"Korok257.jpg"},{"id":"Seed258","no":258,"hint_en":"Lift the metal door with Magnesis, then the little rock with your bulging muscles.","hint_cn":"用磁力抬起金属门，再用肌肉举起小石头","img":"Korok258.jpg"},{"id":"Seed259","no":259,"hint_en":"Blow up the cracked boulders on top of the temple entrance and lift up the small rock hidden underneath.","hint_cn":"炸碎神庙入口顶裂纹巨石，举起下面隐藏的小石头","img":"Korok259.jpg"},{"id":"Seed260","no":260,"hint_en":"Use Magnesis to move the metal door away, then lift up the small rock hidden underneath.","hint_cn":"用磁力移开金属门，举起下面隐藏的小石头","img":"Korok260.jpg"},{"id":"Seed261","no":261,"hint_en":"Under a rock on top of the pillar.","hint_cn":"柱子顶上石头底下","img":"Korok261.jpg"},{"id":"Seed262","no":262,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok262.jpg"},{"id":"Seed263","no":263,"hint_en":"Stand near the pinwheel and shoot all three balloon targets.","hint_cn":"站在风车旁射三个气球靶","img":"Korok263.jpg"},{"id":"Seed264","no":264,"hint_en":"Jump or dive into the ring of flowers in the water.","hint_cn":"跳下或跳入水中花圈","img":"Korok264.jpg"},{"id":"Seed265","no":265,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok265.jpg"},{"id":"Seed266","no":266,"hint_en":"Run through the yellow flower patches in order from 1 to 5. Patch 5 is in the tree behind patch 4.","hint_cn":"按1到5顺序跑过黄花丛。第5丛在第4丛后面的树上","img":"Korok266.jpg"},{"id":"Seed267","no":267,"hint_en":"Remove apples from the tree with too many until it looks like the other two.","hint_cn":"从苹果过多的树上摘果使其和另外两棵一样","img":"Korok267.jpg"},{"id":"Seed268","no":268,"hint_en":"Use Magnesis to lift the chained metal boulder into the center of the stone pillars.","hint_cn":"用磁力把链上金属巨石抬到石柱中心","img":"Korok268.jpg"},{"id":"Seed269","no":269,"hint_en":"Halfway down the northern waterfall there's a ledge with a rock. Pick up the rock.","hint_cn":"北瀑布半腰有个壁架带块石头。捡起","img":"Korok269.jpg"},{"id":"Seed270","no":270,"hint_en":"Melt the ice.","hint_cn":"融化冰块","img":"Korok270.jpg"},{"id":"Seed271","no":271,"hint_en":"Climb the pillar, pick up the rock.","hint_cn":"爬柱子捡起石头","img":"Korok271.jpg"},{"id":"Seed272","no":272,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok272.jpg"},{"id":"Seed273","no":273,"hint_en":"The seed platform is on the tree just to the east. Race to the ring.","hint_cn":"种子平台在东边树上。赛跑至圆环","img":"Korok273.jpg"},{"id":"Seed274","no":274,"hint_en":"Climb up to the seed platform a short bit to the north, then race to the ring.","hint_cn":"爬上北边种子平台，然后赛跑至圆环","img":"Korok274.jpg"},{"id":"Seed275","no":275,"hint_en":"Put an apple in the empty basket near the statue so that both baskets match.","hint_cn":"在雕像旁空篮子里放苹果使两篮匹配","img":"Korok275.jpg"},{"id":"Seed276","no":276,"hint_en":"Solve the Magnesis block puzzle. The block you need is in the lake.","hint_cn":"解开磁力方块拼图。需要的方块在湖里","img":"Korok276.jpg"},{"id":"Seed277","no":277,"hint_en":"Jump/dive into the ring of water lilies.","hint_cn":"跳入或跳入睡莲圈","img":"Korok277.jpg"},{"id":"Seed278","no":278,"hint_en":"The flower trail starts in the stump to the west.","hint_cn":"花径从西边树桩开始","img":"Korok278.jpg"},{"id":"Seed279","no":279,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok279.jpg"},{"id":"Seed280","no":280,"hint_en":"The first flower in this trail is southeast of the Voo Lota Shrine location, just past the tree.","hint_cn":"这条花径第一朵在呜·洛塔神庙位置东南，刚过树","img":"Korok280.jpg"},{"id":"Seed281","no":281,"hint_en":"Under a rock under a pile of leaves.","hint_cn":"树叶堆下石头底下","img":"Korok281.jpg"},{"id":"Seed282","no":282,"hint_en":"Complete the stone circle.","hint_cn":"完成石圈","img":"Korok282.jpg"},{"id":"Seed283","no":283,"hint_en":"Dive or jump into the circle of water lilies.","hint_cn":"跳下或跳入睡莲圈","img":"Korok283.jpg"},{"id":"Seed284","no":284,"hint_en":"Stand on the seed platform found on the large cliff southwest of here (jutting out from the eastern cliff face), and then race to the ring before the time runs out.","hint_cn":"站在西南大悬崖上的种子平台（从东面崖壁突出），限时赛跑至圆环","img":"Korok284.jpg"},{"id":"Seed285","no":285,"hint_en":"Catch the fairy lights that run around in the area.","hint_cn":"抓住绕区域跑的精灵光点","img":"Korok285.jpg"},{"id":"Seed286","no":286,"hint_en":"Solve the block-puzzle by using Magnesis.","hint_cn":"用磁力解开方块拼图","img":"Korok286.jpg"},{"id":"Seed287","no":287,"hint_en":"Throw a rock into the circle of rocks in the pond.","hint_cn":"把石头扔进池塘石圈","img":"Korok287.jpg"},{"id":"Seed288","no":288,"hint_en":"Put two magnetic rocks into two hollowed out tree stumps.","hint_cn":"把两块磁力石头放进两个空心树桩","img":"Korok288.jpg"},{"id":"Seed289","no":289,"hint_en":"Run through each of the flower bunches in order from least to most. To reach the fourth flower bunch inside the hollow tree surrounded by thorns you can burn away the thorns, or glide down from a nearby tree.","hint_cn":"按从少到多顺序跑过每束花。要到荆棘围空心树内第四束，可以烧掉荆棘或从附近树滑翔下去","img":"Korok289.jpg"},{"id":"Seed290","no":290,"hint_en":"Blow up the boulders, pick up the rock.","hint_cn":"炸碎巨石，捡起石头","img":"Korok290.jpg"},{"id":"Seed291","no":291,"hint_en":"Complete the circle of rocks.","hint_cn":"完成石圈","img":"Korok291.jpg"},{"id":"Seed292","no":292,"hint_en":"Climb up the dead tree in in the hollow stump next to the shrine. Examine the fairy lights at the top.","hint_cn":"爬上神庙旁空心树桩里的枯树。顶上查看精灵光点","img":"Korok292.jpg"},{"id":"Seed293","no":293,"hint_en":"Roll a boulder into the pond below.","hint_cn":"把巨石滚进下方池塘","img":"Korok293.jpg"},{"id":"Seed294","no":294,"hint_en":"","hint_cn":"","img":"Korok294.jpg"},{"id":"Seed295","no":295,"hint_en":"Find a nearby small rock just to the west underneath a Bokoblin camp. Bring it over to the stone circle and drop it in place to reveal the Korok.","hint_cn":"在西端波克布林营地下面找小石头。搬到石圈放下露出克洛格","img":"Korok295.jpg"},{"id":"Seed296","no":296,"hint_en":"The seed platform is to the southwest, at the top of the tall rock pillar arching over the road. Race to the ring.","hint_cn":"种子平台在西南，横跨道路的高大石柱拱顶。赛跑至圆环","img":"Korok296.jpg"},{"id":"Seed297","no":297,"hint_en":"Dive into the circle below.","hint_cn":"跳入下方圆圈","img":"Korok297.jpg"},{"id":"Seed298","no":298,"hint_en":"Use Magnesis on the metal cube that's in the nearby broken down house. Match the box puzzle, making the patterns identical.","hint_cn":"用磁力移动附近破屋金属方块。匹配方块拼图图案","img":"Korok298.jpg"},{"id":"Seed299","no":299,"hint_en":"Under a rock behind corrupted area. Shoot the eye to clear the Malice.","hint_cn":"瘴气区后石头底下。射眼睛清瘴气","img":"Korok299.jpg"},{"id":"Seed300","no":300,"hint_en":"Solve the cube puzzle. The cube is in the water.","hint_cn":"解开方块拼图。方块在水里","img":"Korok300.jpg"},{"id":"Seed301","no":301,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok301.jpg"},{"id":"Seed302","no":302,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok302.jpg"},{"id":"Seed303","no":303,"hint_en":"Climb the thin rock pillar next to Gerudo Stables, and lift the rock.","hint_cn":"爬格鲁德驿站旁细石柱，举起石头","img":"Korok303.jpg"},{"id":"Seed304","no":304,"hint_en":"Lift up the small rock.","hint_cn":"举起小石头","img":"Korok304.jpg"},{"id":"Seed305","no":305,"hint_en":"Shoot the hanging acorn.","hint_cn":"射悬挂的橡果","img":"Korok305.jpg"},{"id":"Seed306","no":306,"hint_en":"Put a rock in the middle of the stone rings.","hint_cn":"把石头放进石圈中心","img":"Korok306.jpg"},{"id":"Seed307","no":307,"hint_en":"Use Magnesis to put the iron ball in the treestump.","hint_cn":"用磁力把铁球放进树桩","img":"Korok307.jpg"},{"id":"Seed308","no":308,"hint_en":"Put apples in all offering bowls that are missing one.","hint_cn":"给所有缺的供碗放苹果","img":"Korok308.jpg"},{"id":"Seed309","no":309,"hint_en":"Under a rock on top of a stone pillar.","hint_cn":"石柱顶石头底下","img":"Korok309.jpg"},{"id":"Seed310","no":310,"hint_en":"Run through the patches of flowers 1-5.","hint_cn":"按1到5跑过花丛","img":"Korok310.jpg"},{"id":"Seed311","no":311,"hint_en":"Complete the circle of rocks.","hint_cn":"完成石圈","img":"Korok311.jpg"},{"id":"Seed312","no":312,"hint_en":"Under the rock.","hint_cn":"石头底下","img":"Korok312.jpg"},{"id":"Seed313","no":313,"hint_en":"Dive/jump into the circle of water lilies.","hint_cn":"跳入或跳入睡莲圈","img":"Korok313.jpg"},{"id":"Seed314","no":314,"hint_en":"Stand next to the pinwheel and shoot down all five balloon targets.","hint_cn":"站在风车旁射下五个气球靶","img":"Korok314.jpg"},{"id":"Seed315","no":315,"hint_en":"Under the overhang in the cave, fill the remaining bowls with an apple.","hint_cn":"在洞壁悬垂下方，给剩余碗里放苹果","img":"Korok315.jpg"},{"id":"Seed316","no":316,"hint_en":"Complete the rock circle. The rock is in the direction of the open gap (west).","hint_cn":"完成石圈。石头在缺口方向（西）","img":"Korok316.jpg"},{"id":"Seed317","no":317,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok317.jpg"},{"id":"Seed318","no":318,"hint_en":"","hint_cn":"","img":"Korok318.jpg"},{"id":"Seed319","no":319,"hint_en":"From on top of the well, shoot the balloons as they fly behind the trees.","hint_cn":"从井口上射树后飞过的气球","img":"Korok319.jpg"},{"id":"Seed320","no":320,"hint_en":"Box Puzzle. Make the two patterns identical using Magnesis on the metal box.","hint_cn":"方块拼图。用磁力移动金属箱使两图案相同","img":"Korok320.jpg"},{"id":"Seed321","no":321,"hint_en":"Follow the trail of flowers across the stone crossing.","hint_cn":"跟随穿过石桥的花径","img":"Korok321.jpg"},{"id":"Seed322","no":322,"hint_en":"Directly to the north, wedged between two cliffs are some boulders. Roll one of them down the small ravine and into the hole.","hint_cn":"正北方两悬崖间有巨石。沿小峡谷滚一块进坑里","img":"Korok322.jpg"},{"id":"Seed323","no":323,"hint_en":"Climb the tree, pick up the rock.","hint_cn":"爬树捡起石头","img":"Korok323.jpg"},{"id":"Seed324","no":324,"hint_en":"Throw a rock into the circle of rocks.","hint_cn":"把石头扔进石圈","img":"Korok324.jpg"},{"id":"Seed325","no":325,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok325.jpg"},{"id":"Seed326","no":326,"hint_en":"Stand near the pinwheel, shoot the nearby flying acorns.","hint_cn":"站在风车旁，射附近飞橡果","img":"Korok326.jpg"},{"id":"Seed327","no":327,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok327.jpg"},{"id":"Seed328","no":328,"hint_en":"Climb the tallest tree and examine the fairy lights at the top.","hint_cn":"爬最高的树查看顶部精灵光点","img":"Korok328.jpg"},{"id":"Seed329","no":329,"hint_en":"One tree has too many apples. Make it look like the others.","hint_cn":"一棵苹果树太多苹果。让它和其他一样","img":"Korok329.jpg"},{"id":"Seed330","no":330,"hint_en":"Under a rock under a pile of leaves.","hint_cn":"树叶堆下石头底下","img":"Korok330.jpg"},{"id":"Seed331","no":331,"hint_en":"Drop an apple in the offering bowl.","hint_cn":"把苹果丢进供碗","img":"Korok331.jpg"},{"id":"Seed332","no":332,"hint_en":"Bowl the boulder into the hole. The boulder is uphill to the southeast.","hint_cn":"把巨石滚进坑里。巨石在东南坡上","img":"Korok332.jpg"},{"id":"Seed333","no":333,"hint_en":"Melt the block of ice. Cold Resistance Level 2 recommended.","hint_cn":"融化冰块。建议耐寒等级2","img":"Korok333.jpg"},{"id":"Seed334","no":334,"hint_en":"Push the center boulder to where it belongs.","hint_cn":"把中心巨石推到该在的地方","img":"Korok334.jpg"},{"id":"Seed335","no":335,"hint_en":"This seed starts at a seed platform next to the tree on the peak to the east of this location. Start the race, then quickly glide and climb over to the closer tree. Climb to the very top of this tree, and then glide to the ring to get the seed. Cold Resistance Level 2 recommended.","hint_cn":"种子从本位置东边峰顶树旁种子平台开始。开始赛跑，快速滑翔爬到更近的树。爬到树顶再滑翔到圆环取种子。建议耐寒等级2","img":"Korok335.jpg"},{"id":"Seed336","no":336,"hint_en":"Put a rock in the gap to finish the circle. The rock you need is to the northwest.","hint_cn":"把石头放进缺口补全圆圈。需要的石头在西北","img":"Korok336.jpg"},{"id":"Seed337","no":337,"hint_en":"Fairy lights on top of the hut.","hint_cn":"小屋顶上精灵光点","img":"Korok337.jpg"},{"id":"Seed338","no":338,"hint_en":"Climb to the top of the tree in the middle of the lake, and pick up the rock.","hint_cn":"爬到湖中心树顶捡起石头","img":"Korok338.jpg"},{"id":"Seed339","no":339,"hint_en":"Stand on the leaf stump (located north and slightly east), and then race to the circle before time runs out. Cold Resistance Level 2 recommended.","hint_cn":"站在叶树桩（北偏东）上，限时赛跑至圆环。建议耐寒等级2","img":"Korok339.jpg"},{"id":"Seed340","no":340,"hint_en":"Jump or dive into the circle of water lilies.","hint_cn":"跳下或跳入睡莲圈","img":"Korok340.jpg"},{"id":"Seed341","no":341,"hint_en":"Place a rock to finish the circle. The rock you need is to the east.","hint_cn":"放石头补全圆圈。需要的石头在东边","img":"Korok341.jpg"},{"id":"Seed342","no":342,"hint_en":"Place a Hearty Durian in the leaf at the base of the easternmost statue.","hint_cn":"在最东雕像底部叶子上放榴莲","img":"Korok342.jpg"},{"id":"Seed343","no":343,"hint_en":"Pick up the rock near the pile of dead guardians.","hint_cn":"捡起死守护者堆旁的石头","img":"Korok343.jpg"},{"id":"Seed344","no":344,"hint_en":"Jump or dive into the circle of water lilies.","hint_cn":"跳下或跳入睡莲圈","img":"Korok344.jpg"},{"id":"Seed345","no":345,"hint_en":"Blast the boulders then pick up the small rock.","hint_cn":"炸碎巨石，捡起小石头","img":"Korok345.jpg"},{"id":"Seed346","no":346,"hint_en":"Fairy Lights are circling the location. Catch them. Cold Resistance Level 2 recommended.","hint_cn":"精灵光点绕区域盘旋。抓住。建议耐寒等级2","img":"Korok346.jpg"},{"id":"Seed347","no":347,"hint_en":"Jump into the ring of water lilies.","hint_cn":"跳入睡莲圈","img":"Korok347.jpg"},{"id":"Seed348","no":348,"hint_en":"Climb the small pillar, pick up the small rock.","hint_cn":"爬小柱子捡起小石头","img":"Korok348.jpg"},{"id":"Seed349","no":349,"hint_en":"Pick up the rock on the wooden platform just down the cliff.","hint_cn":"捡起崖下木平台上的石头","img":"Korok349.jpg"},{"id":"Seed350","no":350,"hint_en":"The flower trail starts on the southwest side of the hill. Follow it to the peak.","hint_cn":"花径从山西南侧开始。跟随到峰顶","img":"Korok350.jpg"},{"id":"Seed351","no":351,"hint_en":"This long distance flower trail starts all the way at the top of the hill to the southwest. Specifically beginning at the end of the broken staircase in the ruins on top of the hill.","hint_cn":"这条长花径从西南山顶全程开始。具体从山顶遗迹断梯尽头开始","img":"Korok351.jpg"},{"id":"Seed352","no":352,"hint_en":"Solve the block puzzle. The cube is located on top of the ruins to the west.","hint_cn":"解开方块拼图。方块在西边遗迹顶","img":"Korok352.jpg"},{"id":"Seed353","no":353,"hint_en":"Activate the timer by standing on the seed platform, then quickly race to the top of the two angled pillars and jump off before the time runs out.","hint_cn":"站种子平台激活计时，快速赛跑至双斜柱顶跳下，别超时","img":"Korok353.jpg"},{"id":"Seed354","no":354,"hint_en":"Find the pinwheel on the far end of the castle wall. Shoot five balloons to reveal the Korok.","hint_cn":"在城堡墙远端找风车。射五个气球露出克洛格","img":"Korok354.jpg"},{"id":"Seed355","no":355,"hint_en":"The seed platform is on the Sanctum balcony. Reach the spire before time runs out.","hint_cn":"种子平台在圣所阳台。限时到尖塔","img":"Korok355.jpg"},{"id":"Seed356","no":356,"hint_en":"In the tower at the top of the castle, shoot the balloon hiding above the bell.","hint_cn":"在城堡顶塔里，射藏在钟上方的气球","img":"Korok356.jpg"},{"id":"Seed357","no":357,"hint_en":"Climb the castle to the very top of the spire and examine the fairy lights.","hint_cn":"爬到城堡最尖顶查看精灵光点","img":"Korok357.jpg"},{"id":"Seed358","no":358,"hint_en":"Climb to the top of the spire on the roof of the Second Gatehouse.","hint_cn":"爬到第二门屋顶尖塔顶","img":"Korok358.jpg"},{"id":"Seed359","no":359,"hint_en":"From outside, head through the Dining Hall and into the corridor on the other side. From there, follow the left wall to find a bombable wall in a corridor before the next room. Break it and shoot the acorn hanging above the statue holding the Rusty Claymore, to reveal a Korok.","hint_cn":"从外面进餐厅，走到另一头走廊。沿左墙找下个房间前走廊里可炸墙。炸开，射持锈剑雕像上方悬挂的橡果露出克洛格","img":"Korok359.jpg"},{"id":"Seed360","no":360,"hint_en":"Blow up the wall to reveal the rock.","hint_cn":"炸墙露出石头","img":"Korok360.jpg"},{"id":"Seed361","no":361,"hint_en":"Follow the order of the flowers. The first flower is on the dead guardian next to the group of two flowers.","hint_cn":"按花的顺序。第一朵花在两丛花旁的死守护者上","img":"Korok361.jpg"},{"id":"Seed362","no":362,"hint_en":"Finish the magnetic block puzzle with the block submerged to the east.","hint_cn":"用东边水下方块完成磁力方块拼图","img":"Korok362.jpg"},{"id":"Seed363","no":363,"hint_en":"Place a rock to complete the circle. The rock you need is to the east by some bare trees; use Stasis to help you find it. Cold Resistance Level 2 recommended.","hint_cn":"放石头补全圆圈。需要的石头东边裸树旁，用静止器辅助找。建议耐寒等级2","img":"Korok363.jpg"},{"id":"Seed364","no":364,"hint_en":"A balloon is next to some of the supports for the rock bridge. Shoot it to get the seed.","hint_cn":"石桥支架旁有个气球。射它取种子","img":"Korok364.jpg"},{"id":"Seed365","no":365,"hint_en":"Run through the flowers in order.","hint_cn":"按顺序跑花","img":"Korok365.jpg"},{"id":"Seed366","no":366,"hint_en":"Use the nearby rock to complete the circle.","hint_cn":"用附近石头补全圆圈","img":"Korok366.jpg"},{"id":"Seed367","no":367,"hint_en":"The race starts west of the seed's location. You can face the nearby shrine and climb the snow path to the right up a ways to find the seed platform which starts the race.","hint_cn":"赛跑从种子位置西边开始。面向附近神庙从右边雪路上爬一段找种子平台开始赛跑","img":"Korok367.jpg"},{"id":"Seed368","no":368,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok368.jpg"},{"id":"Seed369","no":369,"hint_en":"Jump into the ring of water lilies.","hint_cn":"跳入睡莲圈","img":"Korok369.jpg"},{"id":"Seed370","no":370,"hint_en":"Use Magnesis to move the iron boulder into the dug out tree stump.","hint_cn":"用磁力把铁巨石移进挖空树桩","img":"Korok370.jpg"},{"id":"Seed371","no":371,"hint_en":"Jump, dive, or fall into the ring of water lilies.","hint_cn":"跳、潜或跌入睡莲圈","img":"Korok371.jpg"},{"id":"Seed372","no":372,"hint_en":"Under the rock.","hint_cn":"石头底下","img":"Korok372.jpg"},{"id":"Seed373","no":373,"hint_en":"Use Magnesis to move the chained rock into the stump.","hint_cn":"用磁力把链上石头移进树桩","img":"Korok373.jpg"},{"id":"Seed374","no":374,"hint_en":"Seed is under a metal door in the middle of some ruins.","hint_cn":"种子在遗迹中间金属门下","img":"Korok374.jpg"},{"id":"Seed375","no":375,"hint_en":"The flower trail to this seed starts at the top of the hill directly to the west. Cold Resistance Level 2 recommended.","hint_cn":"这个种子的花径从正西山顶开始。建议耐寒等级2","img":"Korok375.jpg"},{"id":"Seed376","no":376,"hint_en":"Jump or dive into the circle of lilies in the water.","hint_cn":"跳下或跳入水中睡莲圈","img":"Korok376.jpg"},{"id":"Seed377","no":377,"hint_en":"This short flower trail begins on the coast on the way to the seed.","hint_cn":"这条短花径在去种子的海岸边开始","img":"Korok377.jpg"},{"id":"Seed378","no":378,"hint_en":"Dive into the circle of floating seaweed.","hint_cn":"跳入漂浮海藻圈","img":"Korok378.jpg"},{"id":"Seed379","no":379,"hint_en":"Drop a rock to complete the circle. The rock is downhill in the direction of the open spot (southwest).","hint_cn":"丢石头补全圆圈。石头在开阔处方向（西南）坡下","img":"Korok379.jpg"},{"id":"Seed380","no":380,"hint_en":"Just below the top of the cliff is a small ledge with a rock. Pick it up.","hint_cn":"崖顶稍下有个小石架带块石头。捡起","img":"Korok380.jpg"},{"id":"Seed381","no":381,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok381.jpg"},{"id":"Seed382","no":382,"hint_en":"Under a rock behind some destructible rocks.","hint_cn":"可碎石后石头底下","img":"Korok382.jpg"},{"id":"Seed383","no":383,"hint_en":"Roll a giant boulder from uphill to the south down into the dug out pit.","hint_cn":"从南边坡上滚巨石进挖空坑","img":"Korok383.jpg"},{"id":"Seed384","no":384,"hint_en":"Remove apples from the tree with many to have it match the other two.","hint_cn":"从苹果过多的树上摘果使其和另外两棵一样","img":"Korok384.jpg"},{"id":"Seed385","no":385,"hint_en":"Complete the spiral rock pattern.","hint_cn":"完成螺旋石图案","img":"Korok385.jpg"},{"id":"Seed386","no":386,"hint_en":"Shoot the acorn hidden in the tree trunk.","hint_cn":"射树干里藏的橡果","img":"Korok386.jpg"},{"id":"Seed387","no":387,"hint_en":"Pick up this rock.","hint_cn":"捡起这块石头","img":"Korok387.jpg"},{"id":"Seed388","no":388,"hint_en":"Under the rock.","hint_cn":"石头底下","img":"Korok388.jpg"},{"id":"Seed389","no":389,"hint_en":"Jump or fall into the ring of water lilies.","hint_cn":"跳或跌入睡莲圈","img":"Korok389.jpg"},{"id":"Seed390","no":390,"hint_en":"Stand next to the pinwheel and shoot the three balloons. Cold Resistance Level 2 recommended","hint_cn":"站在风车旁射三个气球。建议耐寒等级2","img":"Korok390.jpg"},{"id":"Seed391","no":391,"hint_en":"One of the trees has too many apples. Remove them until it matches the other two.","hint_cn":"其中一棵树苹果太多。摘到和另外两棵一样","img":"Korok391.jpg"},{"id":"Seed392","no":392,"hint_en":"Shoot the acorn in the tree.","hint_cn":"射树上的橡果","img":"Korok392.jpg"},{"id":"Seed393","no":393,"hint_en":"The nearby dirt road makes a loop; along that loop are 10 signs with bullseye targets. Shoot them all. Back at the cabin, a balloon will appear, shoot it too for the seed.","hint_cn":"附近土路绕一圈，沿路10个靶标牌。全射。回小屋会出现气球，也射取种子","img":"Korok393.jpg"},{"id":"Seed394","no":394,"hint_en":"Under a rock. Cold Resistance Level 2 recommended","hint_cn":"石头底下。建议耐寒等级2","img":"Korok394.jpg"},{"id":"Seed395","no":395,"hint_en":"Under a rock hidden beneath the snowy hill formation. Cold Resistance Level 2 recommended","hint_cn":"雪山岩石构造下隐藏的石头底下。建议耐寒等级2","img":"Korok395.jpg"},{"id":"Seed396","no":396,"hint_en":"Roll the boulder into the hole. Boulders are uphill to the east.","hint_cn":"把巨石滚进坑里。巨石在东边坡上","img":"Korok396.jpg"},{"id":"Seed397","no":397,"hint_en":"Use Magnesis to move the chained rock into the well.","hint_cn":"用磁力把链上石头移进井里","img":"Korok397.jpg"},{"id":"Seed398","no":398,"hint_en":"Pick up the rock to the east of here and place it in the missing spot in the ring of boulders.","hint_cn":"捡起东边石头，放进巨石圈缺失处","img":"Korok398.jpg"},{"id":"Seed399","no":399,"hint_en":"Blow up the rocks here, then pick up the one under them.","hint_cn":"炸碎石块，捡起下面的","img":"Korok399.jpg"},{"id":"Seed400","no":400,"hint_en":"Shoot the acorn in the tree.","hint_cn":"射树上的橡果","img":"Korok400.jpg"},{"id":"Seed401","no":401,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok401.jpg"},{"id":"Seed402","no":402,"hint_en":"Follow the flowers up the bridge support and to the left.","hint_cn":"跟随花径上桥支架往左","img":"Korok402.jpg"},{"id":"Seed403","no":403,"hint_en":"Look to the southeast of the marker, one ledge down, to find the seed platform. Race up the cliff to the circle.","hint_cn":"看标记东南方降一壁架找种子平台。赛跑爬上悬崖至圆环","img":"Korok403.jpg"},{"id":"Seed404","no":404,"hint_en":"Follow the yellow flower trail. It begins east of the mark in the middle of a group of trees, and zigzags a little, going out of the circle of trees then returning nearby.","hint_cn":"跟随黄色花径。起点在标记东边树丛中间，稍曲折，出树丛又回到附近","img":"Korok404.jpg"},{"id":"Seed405","no":405,"hint_en":"Complete the heart shaped rock formation.","hint_cn":"完成心形岩石构造","img":"Korok405.jpg"},{"id":"Seed406","no":406,"hint_en":"Pick up the rock on top of the large tree.","hint_cn":"捡起大树顶上的石头","img":"Korok406.jpg"},{"id":"Seed407","no":407,"hint_en":"Complete the stone circle with a rock by the nearby Bokoblin camp to the north. It will be next to one of the wooden pillars.","hint_cn":"用北边波克布林营地旁的石头完成石圈。在木柱旁","img":"Korok407.jpg"},{"id":"Seed408","no":408,"hint_en":"Complete the rock pattern. The rock you need is just downhill.","hint_cn":"完成石头图案。需要的石头就在坡下","img":"Korok408.jpg"},{"id":"Seed409","no":409,"hint_en":"Put three rocks in the big circular stone formation from the smaller rock formations around it.","hint_cn":"从周围小石阵搬三块石头放进大石阵","img":"Korok409.jpg"},{"id":"Seed410","no":410,"hint_en":"Pick up the stone on the small ledge.","hint_cn":"捡起小壁架上的石头","img":"Korok410.jpg"},{"id":"Seed411","no":411,"hint_en":"Pick up this rock, almost at the top of the cliff.","hint_cn":"捡起这块石头，快到崖顶","img":"Korok411.jpg"},{"id":"Seed412","no":412,"hint_en":"Complete the rock pattern.","hint_cn":"完成石头图案","img":"Korok412.jpg"},{"id":"Seed413","no":413,"hint_en":"The rock needed to complete this stone circle is on the cliff above.","hint_cn":"完成这个石圈需要的石头在上方悬崖","img":"Korok413.jpg"},{"id":"Seed414","no":414,"hint_en":"On the beach is a ring of rocks with one spot missing. Find the nearby boulder (close to the palm tree), pick it up and drop it into the missing spot.","hint_cn":"海滩上有个缺一处的石圈。找附近巨石（棕榈树旁），搬起放进缺失处","img":"Korok414.jpg"},{"id":"Seed415","no":415,"hint_en":"Stand next to the pinwheel, shoot the balloon. Cold Resistance Level 2 recommended.","hint_cn":"站在风车旁射气球。建议耐寒等级2","img":"Korok415.jpg"},{"id":"Seed416","no":416,"hint_en":"Melt the left piece of ice to reveal leaves to examine. Cold Resistance Level 2 recommended.","hint_cn":"融化左边冰块露出树叶查看。建议耐寒等级2","img":"Korok416.jpg"},{"id":"Seed417","no":417,"hint_en":"Pick up the rock from the center of the circle and put it in the missing spot on the outer circle.","hint_cn":"从圈中心搬石头放到外圈缺失处","img":"Korok417.jpg"},{"id":"Seed418","no":418,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok418.jpg"},{"id":"Seed419","no":419,"hint_en":"Bomb the large pile of rocks, then lift up the small rock that was hidden underneath.","hint_cn":"炸大碎石堆，举起隐藏在下面的小石头","img":"Korok419.jpg"},{"id":"Seed420","no":420,"hint_en":"Follow the yellow flower trail in a loop around the little pond area.","hint_cn":"跟随绕小池塘一圈的黄色花径","img":"Korok420.jpg"},{"id":"Seed421","no":421,"hint_en":"Remove the large rock (use Stasis and hit it), then pick up the smaller.","hint_cn":"移开大石头（用静止器击打），然后搬小石头","img":"Korok421.jpg"},{"id":"Seed422","no":422,"hint_en":"Stand next to the pinwheel and then shoot down all three balloon targets.","hint_cn":"站在风车旁射下三个气球靶","img":"Korok422.jpg"},{"id":"Seed423","no":423,"hint_en":"Fairy lights circle the area. Catch them.","hint_cn":"精灵光点绕区域盘旋。抓住","img":"Korok423.jpg"},{"id":"Seed424","no":424,"hint_en":"Above the Spring of Power on an upper rock layer, a rock sits on top a small hill. Lift it and a Korok will appear to give you a seed.","hint_cn":"力量之泉上方上层岩层，小丘上有块石头。举起克洛格出现给你种子","img":"Korok424.jpg"},{"id":"Seed425","no":425,"hint_en":"Remove apples from the tree with too many to match the other two.","hint_cn":"从苹果过多的树上摘果使其和另外两棵匹配","img":"Korok425.jpg"},{"id":"Seed426","no":426,"hint_en":"Solve the block puzzle. The block is on top of a pillar to the west. You'll need Level 1 cold resistance where the puzzle is.","hint_cn":"解开方块拼图。方块在西边柱顶。拼图处需要耐寒等级1","img":"Korok426.jpg"},{"id":"Seed427","no":427,"hint_en":"Use magnesis to put the rock in the well.","hint_cn":"用磁力把石头放进井里","img":"Korok427.jpg"},{"id":"Seed428","no":428,"hint_en":"Burn away the brambles or float over them, and pick up the rock.","hint_cn":"烧掉荆棘或飘过去，捡起石头","img":"Korok428.jpg"},{"id":"Seed429","no":429,"hint_en":"Fairy lights circle the area. Catch them.","hint_cn":"精灵光点绕区域盘旋。抓住","img":"Korok429.jpg"},{"id":"Seed430","no":430,"hint_en":"Complete the rock triangle.","hint_cn":"完成石三角","img":"Korok430.jpg"},{"id":"Seed431","no":431,"hint_en":"Use the nearby rock to complete the circle.","hint_cn":"用附近石头补全圆圈","img":"Korok431.jpg"},{"id":"Seed432","no":432,"hint_en":"Melt the large chunk of ice.","hint_cn":"融化大冰块","img":"Korok432.jpg"},{"id":"Seed433","no":433,"hint_en":"Use the nearby rock to complete the circle.","hint_cn":"用附近石头补全圆圈","img":"Korok433.jpg"},{"id":"Seed434","no":434,"hint_en":"Use the rock to complete the circle.","hint_cn":"用石头补全圆圈","img":"Korok434.jpg"},{"id":"Seed435","no":435,"hint_en":"Make both rock patterns match.","hint_cn":"使两个石图案匹配","img":"Korok435.jpg"},{"id":"Seed436","no":436,"hint_en":"Shoot the balloon hiding in the tree.","hint_cn":"射树里藏的气球","img":"Korok436.jpg"},{"id":"Seed437","no":437,"hint_en":"Use Magnesis to lift the block out of the water and complete the puzzle.","hint_cn":"用磁力把方块从水里抬出完成拼图","img":"Korok437.jpg"},{"id":"Seed438","no":438,"hint_en":"Move the slab to reveal the rock to pick up.","hint_cn":"移开石板露出石头捡起","img":"Korok438.jpg"},{"id":"Seed439","no":439,"hint_en":"Hit the leaves, then pick up the rock.","hint_cn":"击打树叶，然后捡起石头","img":"Korok439.jpg"},{"id":"Seed440","no":440,"hint_en":"Create a cryonis pillar next to the circle of water lilies and then dive into it.","hint_cn":"在睡莲圈旁造冰柱，然后跳入","img":"Korok440.jpg"},{"id":"Seed441","no":441,"hint_en":"Dive into the circle of lilies.","hint_cn":"跳入睡莲圈","img":"Korok441.jpg"},{"id":"Seed442","no":442,"hint_en":"The seed platform for this race is along the line of the ridge to the southeast. It's the peak just uphill to the west of the Soh Kofi Shrine. Once you reach the seed platform, glide and sprint to the end for your seed.","hint_cn":"这个赛跑种子平台在东南山脊线上。索·库菲神庙西边坡上峰顶。到平台后滑翔冲刺取种子","img":"Korok442.jpg"},{"id":"Seed443","no":443,"hint_en":"Throw a rock into the circle of rocks in the water.","hint_cn":"把石头扔进水中石圈","img":"Korok443.jpg"},{"id":"Seed444","no":444,"hint_en":"Climb to the top of the tree and examine the fairy lights.","hint_cn":"爬到树顶查看精灵光点","img":"Korok444.jpg"},{"id":"Seed445","no":445,"hint_en":"Jump into the circle of seaweed/plants.","hint_cn":"跳入海藻/植物圈","img":"Korok445.jpg"},{"id":"Seed446","no":446,"hint_en":"Get a rock to the roof, and complete the rock triangle. This can be difficult and there are multiple methods.","hint_cn":"把石头搬到屋顶完成石三角。有难度，方法多种","img":"Korok446.jpg"},{"id":"Seed447","no":447,"hint_en":"Clear away the leaves and then lift up the small rock.","hint_cn":"清理树叶然后举起小石头","img":"Korok447.jpg"},{"id":"Seed448","no":448,"hint_en":"Jump or dive into the ring of flower lilies in the water.","hint_cn":"跳下或跳入水中百合花圈","img":"Korok448.jpg"},{"id":"Seed449","no":449,"hint_en":"Climb to the top of the peak here and lift the small rock.","hint_cn":"爬到这里峰顶举起小石头","img":"Korok449.jpg"},{"id":"Seed450","no":450,"hint_en":"Lift the small rock next to this tree, right next to the opening that leads into the tunnel beneath the hill.","hint_cn":"举起这棵树旁小石头，就在通往山下隧道口边","img":"Korok450.jpg"},{"id":"Seed451","no":451,"hint_en":"At the top of this plateau are 3 durian trees. Pluck 2 Hearty Durians to make the west-most tree identical to the other 2 trees.","hint_cn":"这个高原顶有3棵榴莲树。摘2颗榴莲使最西树和另外两棵一样","img":"Korok451.jpg"},{"id":"Seed452","no":452,"hint_en":"The seed platform is at the bottom of the cliff. Climb up to the ring.","hint_cn":"种子平台在崖底。爬上至圆环","img":"Korok452.jpg"},{"id":"Seed453","no":453,"hint_en":"Halfway up the waterfall are two ledges to the left and the right. On one of them is a Magnesis puzzle; the other ledge contains the missing block. Refrain from using Cryonis on the waterfall, since the blocks will come out tilted and will make the cube fall; the range of Magnesis is long enough for the cube to reach the puzzle ledge.","hint_cn":"瀑布半腰左右两个壁架。一个是磁力拼图，另一个有缺失方块。不要在瀑布上造冰（方块会倾斜使立方体掉落），磁力范围够长可到拼图架","img":"Korok453.jpg"},{"id":"Seed454","no":454,"hint_en":"Climb to the top of the tree and stand near the pinwheel. Three balloons will appear. Shoot them all to make the Korok appear. These Balloons are well hidden, including one hanging just below the edge of the tree platform, so look around carefully.","hint_cn":"爬到树顶站风车旁。出现三个气球。全射使克洛格出现。气球藏得很好，包括一个挂在树台边下方，仔细看","img":"Korok454.jpg"},{"id":"Seed455","no":455,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok455.jpg"},{"id":"Seed456","no":456,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok456.jpg"},{"id":"Seed457","no":457,"hint_en":"Throw a rock in the circle of rocks. Getting some height from the ledge to the left and using Cryonis makes it easier.","hint_cn":"把石头扔进石圈。从左边壁架高度用造冰术更容易","img":"Korok457.jpg"},{"id":"Seed458","no":458,"hint_en":"A balloon is floating above the river. Shoot it. Gliding close and using a mid-air shot might help, or just drop a bomb on it like you can for every other balloon","hint_cn":"河上飘着气球。射它。贴近滑翔半空射可能有帮助，或直接像其他气球一样扔炸弹","img":"Korok458.jpg"},{"id":"Seed459","no":459,"hint_en":"Destroy the acorn. Shooting it with an arrow is easiest.","hint_cn":"摧毁橡果。射箭最容易","img":"Korok459.jpg"},{"id":"Seed460","no":460,"hint_en":"Match the apple pattern on the tree.","hint_cn":"匹配树上苹果图案","img":"Korok460.jpg"},{"id":"Seed461","no":461,"hint_en":"Catch the Fairy Lights.","hint_cn":"抓住精灵光点","img":"Korok461.jpg"},{"id":"Seed462","no":462,"hint_en":"Look for a small ledge jutting out of the rock face with a rock on it approximately halfway up the wall.","hint_cn":"在岩壁约半腰找突出小石架带块石头","img":"Korok462.jpg"},{"id":"Seed463","no":463,"hint_en":"Follow the trail of flowers starting from slightly south.","hint_cn":"跟随稍南开始的花径","img":"Korok463.jpg"},{"id":"Seed464","no":464,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok464.jpg"},{"id":"Seed465","no":465,"hint_en":"The flower trail starts downhill to the west, and will involve some climbing to reach the seed.","hint_cn":"花径从西边坡下开始，需要爬一段才能到种子","img":"Korok465.jpg"},{"id":"Seed466","no":466,"hint_en":"In the tail fin of the fish statue on top of Zora's Domain, almost the very highest point, examine the fairy lights.","hint_cn":"在卓拉领地顶鱼雕像尾鳍近最高点处查看精灵光点","img":"Korok466.jpg"},{"id":"Seed467","no":467,"hint_en":"Move the large, flat rock with Stasis or an Octo Balloon, then pick up the rock underneath it.","hint_cn":"用静止器或章鱼气球移开大平石，然后捡起下面石头","img":"Korok467.jpg"},{"id":"Seed468","no":468,"hint_en":"Solve the Magnesis puzzle on the cliff wall (at the lowest level of the quarry). The metal block is on top of the nearby rising to the south.","hint_cn":"解悬崖壁磁力拼图（采石场最低层）。金属方块在南边附近坡顶","img":"Korok468.jpg"},{"id":"Seed469","no":469,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok469.jpg"},{"id":"Seed470","no":470,"hint_en":"From the ground below, look up into the overhanging rock and shoot the lone balloon.","hint_cn":"从下方地面看上方悬岩射孤气球","img":"Korok470.jpg"},{"id":"Seed471","no":471,"hint_en":"Climb up here and pick up the rock.","hint_cn":"爬上来捡起石头","img":"Korok471.jpg"},{"id":"Seed472","no":472,"hint_en":"On top of a flagpole.","hint_cn":"旗杆顶上","img":"Korok472.jpg"},{"id":"Seed473","no":473,"hint_en":"Look across the river for a boulder. Use Magnesis to carry the large metal boulder to the hole.","hint_cn":"过河找巨石。用磁力搬大金属巨石到坑","img":"Korok473.jpg"},{"id":"Seed474","no":474,"hint_en":"Follow the flower trail up the hill.","hint_cn":"跟随花径上山","img":"Korok474.jpg"},{"id":"Seed475","no":475,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok475.jpg"},{"id":"Seed476","no":476,"hint_en":"Stand on the tree stump by the paper windmill and shoot the acorn that is being thrown between two trees to southwest.","hint_cn":"站纸风车旁树桩上射西南两树间抛起的橡果","img":"Korok476.jpg"},{"id":"Seed477","no":477,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok477.jpg"},{"id":"Seed478","no":478,"hint_en":"This one left a clue for you. Bomb the boulders and pick up the rock under them.","hint_cn":"这个留了线索。炸巨石捡起下面石头","img":"Korok478.jpg"},{"id":"Seed479","no":479,"hint_en":"Bomb the rock pile and pick up the rock underneath.","hint_cn":"炸碎石堆捡起下面石头","img":"Korok479.jpg"},{"id":"Seed480","no":480,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok480.jpg"},{"id":"Seed481","no":481,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok481.jpg"},{"id":"Seed482","no":482,"hint_en":"The flower trail starts to the east, follow it through the tunnel to the west.","hint_cn":"花径从东边开始，跟随它穿过隧道向西","img":"Korok482.jpg"},{"id":"Seed483","no":483,"hint_en":"Clear the leaves, pick up the rock beneath.","hint_cn":"清理树叶捡起下面石头","img":"Korok483.jpg"},{"id":"Seed484","no":484,"hint_en":"Complete the rock circle using the rock at the other end of the beach.","hint_cn":"用海滩另一端的石头完成石圈","img":"Korok484.jpg"},{"id":"Seed485","no":485,"hint_en":"Blow up the boulders, pick up the rock underneath.","hint_cn":"炸巨石捡起下面石头","img":"Korok485.jpg"},{"id":"Seed486","no":486,"hint_en":"Under a rock on top of a tree.","hint_cn":"树顶石头底下","img":"Korok486.jpg"},{"id":"Seed487","no":487,"hint_en":"Pick up this rock.","hint_cn":"捡起这块石头","img":"Korok487.jpg"},{"id":"Seed488","no":488,"hint_en":"Make the three trees identical by picking apples.","hint_cn":"通过摘苹果使三棵树相同","img":"Korok488.jpg"},{"id":"Seed489","no":489,"hint_en":"Lift the big rock with an Octo Balloon, then pick up the small rock yourself.","hint_cn":"用章鱼气球举起大石头，然后自己捡小石头","img":"Korok489.jpg"},{"id":"Seed490","no":490,"hint_en":"Shoot the balloon inside the big stone arch.","hint_cn":"射大石拱里的气球","img":"Korok490.jpg"},{"id":"Seed491","no":491,"hint_en":"The flower trail for this starts up the cliffs to the west, in the grove.","hint_cn":"这个花径从西边崖上树丛开始","img":"Korok491.jpg"},{"id":"Seed492","no":492,"hint_en":"Start the race on the seed platform to the south and slightly west. Race up to the cliff edge before the time runs out.","hint_cn":"在南偏西种子平台开始赛跑。限时赛跑至崖边","img":"Korok492.jpg"},{"id":"Seed493","no":493,"hint_en":"Get the large boulder out of the way and then lift up the small rock hidden underneath it.","hint_cn":"搬开大巨石然后举起隐藏下面的小石头","img":"Korok493.jpg"},{"id":"Seed494","no":494,"hint_en":"Pick up the rock in the hollow stump.","hint_cn":"捡起空心树桩里的石头","img":"Korok494.jpg"},{"id":"Seed495","no":495,"hint_en":"Stand on the patch of grass near the pinwheel, and shoot the three balloons.","hint_cn":"站风车旁草地上射三个气球","img":"Korok495.jpg"},{"id":"Seed496","no":496,"hint_en":"Move the door, pick up the rock.","hint_cn":"移动门捡起石头","img":"Korok496.jpg"},{"id":"Seed497","no":497,"hint_en":"Pick up a nearby rock on the eastern bank and throw it into the stone circle in the river.","hint_cn":"在东岸捡附近石头扔进河里石圈","img":"Korok497.jpg"},{"id":"Seed498","no":498,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok498.jpg"},{"id":"Seed499","no":499,"hint_en":"Use the magnesis block behind the waterfall to complete the cliffside puzzle. Cryonis will be required to reach the puzzle.","hint_cn":"用瀑布后磁力方块完成崖边拼图。需要造冰术到达拼图处","img":"Korok499.jpg"},{"id":"Seed500","no":500,"hint_en":"Catch the fairy lights as they circle around the area.","hint_cn":"抓住绕区域盘旋的精灵光点","img":"Korok500.jpg"},{"id":"Seed501","no":501,"hint_en":"Climb on top of the destroyed building and examine the fairy lights.","hint_cn":"爬上废墟顶查看精灵光点","img":"Korok501.jpg"},{"id":"Seed502","no":502,"hint_en":"Move the leaves to uncover a rock. Pick up the rock.","hint_cn":"移开树叶露出石头。捡起","img":"Korok502.jpg"},{"id":"Seed503","no":503,"hint_en":"Dive into the circle of lilies.","hint_cn":"跳入睡莲圈","img":"Korok503.jpg"},{"id":"Seed504","no":504,"hint_en":"Climb up the rib to the pinwheel and examine the fairy lights.","hint_cn":"爬上肋骨到风车查看精灵光点","img":"Korok504.jpg"},{"id":"Seed505","no":505,"hint_en":"Complete the stone circle using nearby rocks.","hint_cn":"用附近石头完成石圈","img":"Korok505.jpg"},{"id":"Seed506","no":506,"hint_en":"Shoot the balloon in the rock bridge cleft.","hint_cn":"射石桥缝隙里的气球","img":"Korok506.jpg"},{"id":"Seed507","no":507,"hint_en":"Stand on the nearby seed platform and then race to the ring.","hint_cn":"站附近种子平台然后赛跑至圆环","img":"Korok507.jpg"},{"id":"Seed508","no":508,"hint_en":"Examine the fairy lights in the cleft in the rock bridge.","hint_cn":"查看石桥缝隙里的精灵光点","img":"Korok508.jpg"},{"id":"Seed509","no":509,"hint_en":"The seed platform for this race is at the top of the cliff to the northeast. Race to the ring.","hint_cn":"这个赛跑种子平台在东北崖顶。赛跑至圆环","img":"Korok509.jpg"},{"id":"Seed510","no":510,"hint_en":"This flower trail starts directly west, at the bottom of the cliff, and requires you to climb straight up. Bring lots of stamina 3 full bars isn't enough will need to replenish.","hint_cn":"这条花径从正西山底开始，需要直爬。带满体力（3条满不够需要补）","img":"Korok510.jpg"},{"id":"Seed511","no":511,"hint_en":"Push the boulders at the top of the cliff into the hole at the bottom.","hint_cn":"把崖顶巨石推进底部坑里","img":"Korok511.jpg"},{"id":"Seed512","no":512,"hint_en":"The seed platform is on the ledge to the northwest. Race to the ring.","hint_cn":"种子平台在西北壁架上。赛跑至圆环","img":"Korok512.jpg"},{"id":"Seed513","no":513,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok513.jpg"},{"id":"Seed514","no":514,"hint_en":"The flower trail starts inside the tunnel, then works its way up the northern cave entrance.","hint_cn":"花径从隧道内开始，沿北边洞口向上","img":"Korok514.jpg"},{"id":"Seed515","no":515,"hint_en":"Put the rock in the well using Magnesis.","hint_cn":"用磁力把石头放进井里","img":"Korok515.jpg"},{"id":"Seed516","no":516,"hint_en":"On top of the inn, there are 3 palm tree trunks. Climb around these chasing the yellow flower trail.","hint_cn":"旅馆顶上有3根棕榈树干。绕它们追黄色花径","img":"Korok516.jpg"},{"id":"Seed517","no":517,"hint_en":"Remove the apple from between the palm fruits, such as by shooting it.","hint_cn":"从棕榈果间射掉苹果","img":"Korok517.jpg"},{"id":"Seed518","no":518,"hint_en":"Remove two Hearty Durian from the western tree so that all three trees match.","hint_cn":"从西边树摘2颗榴莲使三棵树匹配","img":"Korok518.jpg"},{"id":"Seed519","no":519,"hint_en":"Place Mighty Bananas on the leaf below the statue.","hint_cn":"在雕像下叶子上放香蕉","img":"Korok519.jpg"},{"id":"Seed520","no":520,"hint_en":"Burn the goatee made out of leaves of the Horse structure above the stables.","hint_cn":"烧掉驿站上方马结构用树叶做的胡子","img":"Korok520.jpg"},{"id":"Seed521","no":521,"hint_en":"Remove the Luminous Stone from the eye of the statue.","hint_cn":"从雕像眼睛里取出夜光石","img":"Korok521.jpg"},{"id":"Seed522","no":522,"hint_en":"Lift up the small rock found on top of the ledge here.","hint_cn":"举起这里壁架上的小石头","img":"Korok522.jpg"},{"id":"Seed523","no":523,"hint_en":"This Korok's rock pattern is in the shape of a large spiral. On the second line from the outside is a missing rock, simply complete the pattern with the rock found nearby.","hint_cn":"这个克洛格石图案是大螺旋。从外数第二行缺一块，用附近石头补全","img":"Korok523.jpg"},{"id":"Seed524","no":524,"hint_en":"This race begins at the even taller pillar to the southwest.","hint_cn":"这个赛跑从西南更高柱子开始","img":"Korok524.jpg"},{"id":"Seed525","no":525,"hint_en":"Remove the slab using Stasis or an Octo Balloon since there's several octoroks in the area, then pick up the rock.","hint_cn":"用静止器或章鱼气球移开石板（区域有几只八爪怪），然后捡起石头","img":"Korok525.jpg"},{"id":"Seed526","no":526,"hint_en":"Throw a nearby rock into the ring of stones in the pond. Cryonis might help.","hint_cn":"把附近石头扔进池塘石圈。造冰术可能有帮助","img":"Korok526.jpg"},{"id":"Seed527","no":527,"hint_en":"Follow the yellow flower trail that starts just on the opposite side of the bridge.","hint_cn":"跟随桥对面开始的黄色花径","img":"Korok527.jpg"},{"id":"Seed528","no":528,"hint_en":"Shoot the balloon hidden in the top of the palm tree. It is easiest to spot if you climb up the ledge to the east.","hint_cn":"射棕榈树顶藏的气球。爬上东边壁架最容易发现","img":"Korok528.jpg"},{"id":"Seed529","no":529,"hint_en":"Dive into the ring of lilies.","hint_cn":"跳入睡莲圈","img":"Korok529.jpg"},{"id":"Seed530","no":530,"hint_en":"High on the cliff above this hole are three boulders. Push one of them off the cliff and into the hole.","hint_cn":"这个洞上方高崖有三块巨石。推一块下崖进洞","img":"Korok530.jpg"},{"id":"Seed531","no":531,"hint_en":"Pick up a rock to the north just up the ledge and move it to complete the stone circle.","hint_cn":"北边壁架捡石头移到石圈补全","img":"Korok531.jpg"},{"id":"Seed532","no":532,"hint_en":"Dive into the ring of flower lilies in the water.","hint_cn":"跳入水中百合花圈","img":"Korok532.jpg"},{"id":"Seed533","no":533,"hint_en":"Lift up the small rock at the top of this mountain.","hint_cn":"举起这山顶小石头","img":"Korok533.jpg"},{"id":"Seed534","no":534,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok534.jpg"},{"id":"Seed535","no":535,"hint_en":"Jump into the ring of seaweed to reveal a Korok.","hint_cn":"跳入海藻圈露出克洛格","img":"Korok535.jpg"},{"id":"Seed536","no":536,"hint_en":"Climb to the top of the mushroom shaped pillar and pick up the rock at the top.","hint_cn":"爬到蘑菇形柱顶捡起石头","img":"Korok536.jpg"},{"id":"Seed537","no":537,"hint_en":"Bomb the wall and lift the hidden rock.","hint_cn":"炸墙举起隐藏石头","img":"Korok537.jpg"},{"id":"Seed538","no":538,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok538.jpg"},{"id":"Seed539","no":539,"hint_en":"Climb the palm tree and examine the fairy lights.","hint_cn":"爬棕榈树查看精灵光点","img":"Korok539.jpg"},{"id":"Seed540","no":540,"hint_en":"Drop one cliff level down from the top of the cliff to find a rock to pick up.","hint_cn":"从崖顶降一崖层找石头捡起","img":"Korok540.jpg"},{"id":"Seed541","no":541,"hint_en":"This one is very hard to see. The metal cube is underwater next to the islands, but can only be seen from certain angles (look down where the arrow is in the picture). Then take it to the block puzzle on the cliff, which can be hard to spot. It's on the north side of the cliff.","hint_cn":"这个很难看到。金属方块水下小岛旁，只能从特定角度看到（看箭头指处下方）。然后搬到崖上方块拼图，拼图在崖北側难找","img":"Korok541.jpg"},{"id":"Seed542","no":542,"hint_en":"Bomb the wall in the corner of the hillside then lift the revealed rock.","hint_cn":"炸山坡角落墙然后举起露出的石头","img":"Korok542.jpg"},{"id":"Seed543","no":543,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok543.jpg"},{"id":"Seed544","no":544,"hint_en":"Roll the boulder into the hole.","hint_cn":"把巨石滚进坑里","img":"Korok544.jpg"},{"id":"Seed545","no":545,"hint_en":"Shoot the acorn.","hint_cn":"射橡果","img":"Korok545.jpg"},{"id":"Seed546","no":546,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok546.jpg"},{"id":"Seed547","no":547,"hint_en":"Shoot the balloon.","hint_cn":"射气球","img":"Korok547.jpg"},{"id":"Seed548","no":548,"hint_en":"Move the slab, and pick up the rock under it.","hint_cn":"移动石板，捡起下面石头","img":"Korok548.jpg"},{"id":"Seed549","no":549,"hint_en":"Climb down the bridge to the first set of windows. Pick up the tree branch on the narrow ledge.","hint_cn":"沿桥下到第一排窗户。窄壁架上捡树枝","img":"Korok549.jpg"},{"id":"Seed550","no":550,"hint_en":"Examine the fairy lights at the top of the tree. Refrain from attempting it during a thunderstorm, since lightning will strike and take the tree down.","hint_cn":"查看树顶精灵光点。雷暴时别试，雷击会劈倒树","img":"Korok550.jpg"},{"id":"Seed551","no":551,"hint_en":"Solve the Magnesis block puzzle. The block is in the water nearby.","hint_cn":"解开磁力方块拼图。方块在附近水里","img":"Korok551.jpg"},{"id":"Seed552","no":552,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok552.jpg"},{"id":"Seed553","no":553,"hint_en":"Step on the seed platform on the coast to the west and then race to the ring.","hint_cn":"站西岸种子平台然后赛跑至圆环","img":"Korok553.jpg"},{"id":"Seed554","no":554,"hint_en":"Use Magnesis on the metal cube and bring it to the other side of the waterfall. Use Cryonis on the waterfall to reach the box puzzle above.","hint_cn":"用磁力移动金属方块到瀑布对岸。在瀑布上造冰术到达上方方块拼图","img":"Korok554.jpg"},{"id":"Seed555","no":555,"hint_en":"Use Magnesis to move the chained rock into the stump.","hint_cn":"用磁力把链上石头移进树桩","img":"Korok555.jpg"},{"id":"Seed556","no":556,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok556.jpg"},{"id":"Seed557","no":557,"hint_en":"Solve the block puzzle. The block is in the nearby tree.","hint_cn":"解开方块拼图。方块在附近树上","img":"Korok557.jpg"},{"id":"Seed558","no":558,"hint_en":"There are two fairy lights dancing around here. Catch them both for two seeds.","hint_cn":"这里有两个精灵光点在飞舞。两个都抓可得两个种子","img":"Korok558.jpg"},{"id":"Seed559","no":559,"hint_en":"Lift stone at the top of the hill.","hint_cn":"举起山顶石头","img":"Korok559.jpg"},{"id":"Seed560","no":560,"hint_en":"Stand near the pinwheel, shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok560.jpg"},{"id":"Seed561","no":561,"hint_en":"Roll the boulder into the hole.","hint_cn":"把巨石滚进坑里","img":"Korok561.jpg"},{"id":"Seed562","no":562,"hint_en":"Bomb the nearby breakable wall in the mountainside, then lift the revealed stone.","hint_cn":"炸山腰可破墙，然后举起露出的石头","img":"Korok562.jpg"},{"id":"Seed563","no":563,"hint_en":"Climb up the tree and lift the small rock.","hint_cn":"爬树举起小石头","img":"Korok563.jpg"},{"id":"Seed564","no":564,"hint_en":"Get the boulder off the pillar and to the corner, matching the other three surrounding the statue.","hint_cn":"把巨石从柱子搬到角落，匹配雕像周围另外三个","img":"Korok564.jpg"},{"id":"Seed565","no":565,"hint_en":"Lift the stone above the small waterfall.","hint_cn":"举起小瀑布上方石头","img":"Korok565.jpg"},{"id":"Seed566","no":566,"hint_en":"Interact with the fairy lights floating around the lake.","hint_cn":"与绕湖漂浮的精灵光点互动","img":"Korok566.jpg"},{"id":"Seed567","no":567,"hint_en":"Interact with the fairy lights floating around the area.","hint_cn":"与绕区域漂浮的精灵光点互动","img":"Korok567.jpg"},{"id":"Seed568","no":568,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok568.jpg"},{"id":"Seed569","no":569,"hint_en":"Complete the rock triangle on the island in the tar pit. Knock down a tree to make a bridge.","hint_cn":"在焦油坑小岛上完成石三角。砍树做桥","img":"Korok569.jpg"},{"id":"Seed570","no":570,"hint_en":"The seed platform is visible to the north-northwest. Race to the ring for the seed.","hint_cn":"北偏西北可见种子平台。赛跑至圆环取种子","img":"Korok570.jpg"},{"id":"Seed571","no":571,"hint_en":"Blow up the middle set of boulders, and then pick up the rock.","hint_cn":"炸中间组巨石，然后捡起石头","img":"Korok571.jpg"},{"id":"Seed572","no":572,"hint_en":"Blow up the boulders, then lift up the small rock that was hidden beneath them.","hint_cn":"炸碎巨石，举起隐藏下面的小石头","img":"Korok572.jpg"},{"id":"Seed573","no":573,"hint_en":"Shoot the balloon.","hint_cn":"射气球","img":"Korok573.jpg"},{"id":"Seed574","no":574,"hint_en":"Shoot the acorn hiding inside the end of the hollowed out log.","hint_cn":"射空心原木末端藏的橡果","img":"Korok574.jpg"},{"id":"Seed575","no":575,"hint_en":"Climb the lone tree to the very top and examine the fairy lights.","hint_cn":"爬孤树到顶查看精灵光点","img":"Korok575.jpg"},{"id":"Seed576","no":576,"hint_en":"Shoot the small acorn hanging from the tall tree.","hint_cn":"射高树悬挂的小橡果","img":"Korok576.jpg"},{"id":"Seed577","no":577,"hint_en":"Solve the Magnesis block puzzle.","hint_cn":"解开磁力方块拼图","img":"Korok577.jpg"},{"id":"Seed578","no":578,"hint_en":"Stand near the pinwheel, shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok578.jpg"},{"id":"Seed579","no":579,"hint_en":"Climb the tree and examine the fairy lights.","hint_cn":"爬树查看精灵光点","img":"Korok579.jpg"},{"id":"Seed580","no":580,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok580.jpg"},{"id":"Seed581","no":581,"hint_en":"Shoot the balloon underneath the rock bridge.","hint_cn":"射石桥下方气球","img":"Korok581.jpg"},{"id":"Seed582","no":582,"hint_en":"Pick up the rock on the first ledge from the top of the cliff.","hint_cn":"捡起崖顶第一壁架上的石头","img":"Korok582.jpg"},{"id":"Seed583","no":583,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok583.jpg"},{"id":"Seed584","no":584,"hint_en":"Just to the north is a seed platform on a wooden platform. Race to the ring for the seed.","hint_cn":"北边不远木平台上有种子平台。赛跑至圆环取种子","img":"Korok584.jpg"},{"id":"Seed585","no":585,"hint_en":"Go to the westernmost part of the cliff behind the shrine, climb up 4 cliffs, then pick up the rock.","hint_cn":"到神庙后悬崖最西端，爬4层悬崖，然后捡起石头","img":"Korok585.jpg"},{"id":"Seed586","no":586,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok586.jpg"},{"id":"Seed587","no":587,"hint_en":"Climb the tree, lift the rock.","hint_cn":"爬树，举起石头","img":"Korok587.jpg"},{"id":"Seed588","no":588,"hint_en":"Solve the Magnesis Block puzzle near the top of the cliff.","hint_cn":"解崖顶附近磁力方块拼图","img":"Korok588.jpg"},{"id":"Seed589","no":589,"hint_en":"Shoot the balloon in the tree.","hint_cn":"射树上气球","img":"Korok589.jpg"},{"id":"Seed590","no":590,"hint_en":"Climb up to the seed platform, and then get to the ring, quick.","hint_cn":"爬上种子平台，然后快速到圆环","img":"Korok590.jpg"},{"id":"Seed591","no":591,"hint_en":"Climb to the highest point of the rib structure and examine the fairy lights.","hint_cn":"爬到肋骨结构最高点查看精灵光点","img":"Korok591.jpg"},{"id":"Seed592","no":592,"hint_en":"Climb to the highest point of the rib structure and examine the fairy lights.","hint_cn":"爬到肋骨结构最高点查看精灵光点","img":"Korok592.jpg"},{"id":"Seed593","no":593,"hint_en":"Complete the rock circle. The rock to use is in a corner of the cliff wall.","hint_cn":"完成石圈。要用的石头在崖壁角落","img":"Korok593.jpg"},{"id":"Seed594","no":594,"hint_en":"Follow the flower trail up the wall to the cliff above.","hint_cn":"跟随花径沿墙爬上上方悬崖","img":"Korok594.jpg"},{"id":"Seed595","no":595,"hint_en":"Offer a Mighty Banana to the offering bowl.","hint_cn":"给供碗供奉香蕉","img":"Korok595.jpg"},{"id":"Seed596","no":596,"hint_en":"Offer Mighty Bananas to the two offering bowls.","hint_cn":"给两个供碗供奉香蕉","img":"Korok596.jpg"},{"id":"Seed597","no":597,"hint_en":"Offer Mighty Bananas to the three offering bowls.","hint_cn":"给三个供碗供奉香蕉","img":"Korok597.jpg"},{"id":"Seed598","no":598,"hint_en":"Offer Mighty Bananas to the four offering bowls.","hint_cn":"给四个供碗供奉香蕉","img":"Korok598.jpg"},{"id":"Seed599","no":599,"hint_en":"Offer Mighty Bananas to the five offering bowls.","hint_cn":"给五个供碗供奉香蕉","img":"Korok599.jpg"},{"id":"Seed600","no":600,"hint_en":"Roll the...No, wait, pick up the snowball and place it in the hole.","hint_cn":"滚...不，捡起雪球放进坑里","img":"Korok600.jpg"},{"id":"Seed601","no":601,"hint_en":"This Magnesis puzzle is more spread out than most. Solution is on the west wall, puzzle on the east, and block's in the middle.","hint_cn":"这个磁力拼图比多数分散。答案在西墙，拼图在东，方块在中间","img":"Korok601.jpg"},{"id":"Seed602","no":602,"hint_en":"Find a rock just to the east of the rock circle. Walk along the narrow cliff path to complete the pattern.","hint_cn":"在石圈东边找石头。沿窄崖径走补全图案","img":"Korok602.jpg"},{"id":"Seed603","no":603,"hint_en":"This is a rock circle made up of pieces of 3 rocks each, except for a large rock out of place. Put it in place.","hint_cn":"这是由3块石头组成的石圈，除一块大石放错了。归位","img":"Korok603.jpg"},{"id":"Seed604","no":604,"hint_en":"At the top of this section of the mountain, lift up the small rock.","hint_cn":"在这山段顶举起小石头","img":"Korok604.jpg"},{"id":"Seed605","no":605,"hint_en":"A circle of rocks on this ledge on the side of the mountain is incomplete. Grab the rock from the ledge slightly higher up and bring it down to the ring and complete the circle of rocks. Level 2 Cold Resistance recommended","hint_cn":"山侧壁架上的石圈不完整。从稍高壁架搬石头到圈补全。建议耐寒等级2","img":"Korok605.jpg"},{"id":"Seed606","no":606,"hint_en":"Melt the chunk of ice that's closest to the edge.","hint_cn":"融化最靠边的冰块","img":"Korok606.jpg"},{"id":"Seed607","no":607,"hint_en":"Climb the tree and examine the fairy lights.","hint_cn":"爬树查看精灵光点","img":"Korok607.jpg"},{"id":"Seed608","no":608,"hint_en":"Complete the rock pattern.","hint_cn":"完成石头图案","img":"Korok608.jpg"},{"id":"Seed609","no":609,"hint_en":"Complete the magnetic block puzzle.","hint_cn":"完成磁力方块拼图","img":"Korok609.jpg"},{"id":"Seed610","no":610,"hint_en":"Bomb the rock wall and pick up the rock behind it.","hint_cn":"炸石墙捡起后面石头","img":"Korok610.jpg"},{"id":"Seed611","no":611,"hint_en":"Climb inside of the skeleton's north-facing eye socket, burn or bomb the leaves, then pick up the rock.","hint_cn":"爬进骷髅朝北眼窝，烧或炸树叶，然后捡起石头","img":"Korok611.jpg"},{"id":"Seed612","no":612,"hint_en":"Complete the stone circle using a nearby rock (which is in a clump of bushes to the east as you head to the Lynel.  Stasis can help you see it.).","hint_cn":"用附近石头完成石圈（往人马里走东边灌木丛里，静止器辅助可见）","img":"Korok612.jpg"},{"id":"Seed613","no":613,"hint_en":"Finish the magnetic block puzzle.","hint_cn":"完成磁力方块拼图","img":"Korok613.jpg"},{"id":"Seed614","no":614,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok614.jpg"},{"id":"Seed615","no":615,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok615.jpg"},{"id":"Seed616","no":616,"hint_en":"Finish the rock pattern with a nearby rock.","hint_cn":"用附近石头完成石头图案","img":"Korok616.jpg"},{"id":"Seed617","no":617,"hint_en":"Dive into the circle of lilies at the bottom of the waterfall.","hint_cn":"跳入瀑布底睡莲圈","img":"Korok617.jpg"},{"id":"Seed618","no":618,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok618.jpg"},{"id":"Seed619","no":619,"hint_en":"Lift the rock on top of the structure surrounding the shrine.","hint_cn":"举起围神庙结构顶上的石头","img":"Korok619.jpg"},{"id":"Seed620","no":620,"hint_en":"Shoot the balloon underneath the upper cliff.","hint_cn":"射上方悬崖下的气球","img":"Korok620.jpg"},{"id":"Seed621","no":621,"hint_en":"Complete the magnetic block puzzle in the ruins.","hint_cn":"完成遗迹里磁力方块拼图","img":"Korok621.jpg"},{"id":"Seed622","no":622,"hint_en":"Thaw the ice block and examine the whirling glittering leaves.","hint_cn":"融化冰块查看旋转闪光树叶","img":"Korok622.jpg"},{"id":"Seed623","no":623,"hint_en":"Thaw the ice and examine the fairy lights.","hint_cn":"融化冰块查看精灵光点","img":"Korok623.jpg"},{"id":"Seed624","no":624,"hint_en":"Thaw the ice and examine the whirling glittering leaves.","hint_cn":"融化冰块查看旋转闪光树叶","img":"Korok624.jpg"},{"id":"Seed625","no":625,"hint_en":"Roll a boulder into the hole. Boulders can be found on the nearby hill to the southeast. It is advised to kill the Lynel first.","hint_cn":"把巨石滚进坑里。巨石在附近东南山上。建议先杀人马","img":"Korok625.jpg"},{"id":"Seed626","no":626,"hint_en":"Break the nut in the hole in the tree.","hint_cn":"敲碎树洞坚果","img":"Korok626.jpg"},{"id":"Seed627","no":627,"hint_en":"Shoot five balloons near the pinwheel.","hint_cn":"在风车旁射五个气球","img":"Korok627.jpg"},{"id":"Seed628","no":628,"hint_en":"Destroy the acorn in the hole in the side of the tree.","hint_cn":"摧毁树干侧面洞里的橡果","img":"Korok628.jpg"},{"id":"Seed629","no":629,"hint_en":"Break the nut in the hole of the fallen tree.","hint_cn":"敲碎倒树洞里的坚果","img":"Korok629.jpg"},{"id":"Seed630","no":630,"hint_en":"Hidden under a small rock that is covered by the leaves.","hint_cn":"藏在树叶覆盖的小石头下","img":"Korok630.jpg"},{"id":"Seed631","no":631,"hint_en":"Roll a boulder (found to the north) into the hole.","hint_cn":"把巨石（北边找到）滚进坑里","img":"Korok631.jpg"},{"id":"Seed632","no":632,"hint_en":"Use a bladed weapon to clear the leaves and then lift the small rock that was hidden underneath.","hint_cn":"用斩草武器清理树叶，然后举起隐藏下面的小石头","img":"Korok632.jpg"},{"id":"Seed633","no":633,"hint_en":"Race from the top of the mountain to the northwest.","hint_cn":"从西北山顶开始赛跑","img":"Korok633.jpg"},{"id":"Seed634","no":634,"hint_en":"Finish the rock pattern using a rock on a nearby ledge to the south.","hint_cn":"用南边附近壁架上石头完成石头图案","img":"Korok634.jpg"},{"id":"Seed635","no":635,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok635.jpg"},{"id":"Seed636","no":636,"hint_en":"Push the nearby boulder into the hole.","hint_cn":"把附近巨石推进坑里","img":"Korok636.jpg"},{"id":"Seed637","no":637,"hint_en":"The pinwheel at the top of this section of wall spawns balloons to the north. Shoot them.","hint_cn":"这段墙顶风车在北边生成气球。射它们","img":"Korok637.jpg"},{"id":"Seed638","no":638,"hint_en":"Climb to the top of the flagpole.","hint_cn":"爬到旗杆顶","img":"Korok638.jpg"},{"id":"Seed639","no":639,"hint_en":"Pick up the rock on the peak of the mountain.","hint_cn":"捡起峰顶石头","img":"Korok639.jpg"},{"id":"Seed640","no":640,"hint_en":"The seed platform is to the southwest, across the chasm. Race to the ring.","hint_cn":"种子平台在西南，横跨深渊。赛跑至圆环","img":"Korok640.jpg"},{"id":"Seed641","no":641,"hint_en":"Look near the cannons for a rock to pick up.","hint_cn":"在大炮附近找石头捡起","img":"Korok641.jpg"},{"id":"Seed642","no":642,"hint_en":"Climb to the top of the cabin and examine the swirling leaves. Cold Resistance Level 2 recommended","hint_cn":"爬到小屋顶查看旋转树叶。建议耐寒等级2","img":"Korok642.jpg"},{"id":"Seed643","no":643,"hint_en":"Complete the circle using two nearby stones.","hint_cn":"用附近两块石头补全圆圈","img":"Korok643.jpg"},{"id":"Seed644","no":644,"hint_en":"Complete the rock circle from the rock next to a nearby lava flow.","hint_cn":"用附近熔岩旁石头完成石圈","img":"Korok644.jpg"},{"id":"Seed645","no":645,"hint_en":"Roll the boulder into the lava at the end of the hill.","hint_cn":"把巨石滚进山坡尽头熔岩里","img":"Korok645.jpg"},{"id":"Seed646","no":646,"hint_en":"Stand near the pinwheel, shoot the balloon.","hint_cn":"站在风车旁射气球","img":"Korok646.jpg"},{"id":"Seed647","no":647,"hint_en":"Thaw the ice block and examine the glittering leaves. Cold Resistance Level 2 recommended","hint_cn":"融化冰块查看闪光树叶。建议耐寒等级2","img":"Korok647.jpg"},{"id":"Seed648","no":648,"hint_en":"Under a rock up the large curved tree.","hint_cn":"大弯树上石头底下","img":"Korok648.jpg"},{"id":"Seed649","no":649,"hint_en":"Shoot the acorn hanging from a tree.","hint_cn":"射树上悬挂橡果","img":"Korok649.jpg"},{"id":"Seed650","no":650,"hint_en":"Put an apple in every bowl.","hint_cn":"每个碗里放苹果","img":"Korok650.jpg"},{"id":"Seed651","no":651,"hint_en":"Under a rock up in a tree.","hint_cn":"树上石头底下","img":"Korok651.jpg"},{"id":"Seed652","no":652,"hint_en":"Follow a trail of flowers that starts slightly to the east.","hint_cn":"跟随稍东开始的花径","img":"Korok652.jpg"},{"id":"Seed653","no":653,"hint_en":"Move the metal door and pick up the rock under it.","hint_cn":"移动金属门捡起下面石头","img":"Korok653.jpg"},{"id":"Seed654","no":654,"hint_en":"Shoot the 3 balloons hiding behind the Malice to reveal the Korok.","hint_cn":"射瘴气后藏的3个气球露出克洛格","img":"Korok654.jpg"},{"id":"Seed655","no":655,"hint_en":"Shoot the balloon in the far distance to reveal the Korok.","hint_cn":"射远处气球露出克洛格","img":"Korok655.jpg"},{"id":"Seed656","no":656,"hint_en":"Dive into the ring in the water.","hint_cn":"跳入水中圆圈","img":"Korok656.jpg"},{"id":"Seed657","no":657,"hint_en":"Shoot the acorn hanging from the tree.","hint_cn":"射树上悬挂橡果","img":"Korok657.jpg"},{"id":"Seed658","no":658,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok658.jpg"},{"id":"Seed659","no":659,"hint_en":"Get one of the giant boulders to the east into the hole.","hint_cn":"把东边一块巨石弄进坑里","img":"Korok659.jpg"},{"id":"Seed660","no":660,"hint_en":"Shoot 3 balloons near the pinwheel.","hint_cn":"在风车旁射3个气球","img":"Korok660.jpg"},{"id":"Seed661","no":661,"hint_en":"Under a rock under a slab.","hint_cn":"石板下石头底下","img":"Korok661.jpg"},{"id":"Seed662","no":662,"hint_en":"Complete the three stone circles using rocks that lie approximately in the direction of each circles gap.","hint_cn":"用大致在各圈缺口方向的石头完成三个石圈","img":"Korok662.jpg"},{"id":"Seed663","no":663,"hint_en":"Find the missing rock to fill in the triangle.","hint_cn":"找缺失石头填三角","img":"Korok663.jpg"},{"id":"Seed664","no":664,"hint_en":"Climb the hill to the west of the marker to find this seed platform. You'll need to shield surf down the hill to reach the circle in time, as it expires very quickly. Cold Resistance Level 2 recommended","hint_cn":"爬标记西山找种子平台。需要盾滑下山及时到圆环，因为很快消失。建议耐寒等级2","img":"Korok664.jpg"},{"id":"Seed665","no":665,"hint_en":"Complete the block puzzle. Cold Resistance Level 2 recommended","hint_cn":"完成方块拼图。建议耐寒等级2","img":"Korok665.jpg"},{"id":"Seed666","no":666,"hint_en":"Climb to the top of the hill to find a pinwheel. The three balloons constantly disappear and reappear over the nearby trees.","hint_cn":"爬到山顶找风车。三个气球不断在附近树上方消失重现","img":"Korok666.jpg"},{"id":"Seed667","no":667,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok667.jpg"},{"id":"Seed668","no":668,"hint_en":"Destroy the acorn in the hollow of the tree log.","hint_cn":"摧毁树洞里的橡果","img":"Korok668.jpg"},{"id":"Seed669","no":669,"hint_en":"Under a rock between the pillars.","hint_cn":"柱子之间石头底下","img":"Korok669.jpg"},{"id":"Seed670","no":670,"hint_en":"Place an apple in the empty basket.","hint_cn":"把苹果放进空篮子","img":"Korok670.jpg"},{"id":"Seed671","no":671,"hint_en":"Complete the circle of rocks. the rock is hidden behind some bushes southwest of the circle.","hint_cn":"完成石圈。石头藏在圈西南灌木丛后","img":"Korok671.jpg"},{"id":"Seed672","no":672,"hint_en":"At the bottom of the canyon, blow up the cracked boulders then lift the small rock hidden behind them.","hint_cn":"峡谷底炸裂纹巨石然后举起隐藏后面小石头","img":"Korok672.jpg"},{"id":"Seed673","no":673,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok673.jpg"},{"id":"Seed674","no":674,"hint_en":"On top of the temple, use Magnesis to put the cube back in its rightful spot.","hint_cn":"神庙顶上用磁力把方块放回正确位置","img":"Korok674.jpg"},{"id":"Seed675","no":675,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok675.jpg"},{"id":"Seed676","no":676,"hint_en":"Race from a lower pillar just to the north-northeast to this high pillar.","hint_cn":"从北偏东北下方矮柱赛跑至高柱","img":"Korok676.jpg"},{"id":"Seed677","no":677,"hint_en":"Climb up to the top of the flagpole and examine the fairy lights.","hint_cn":"爬到旗杆顶查看精灵光点","img":"Korok677.jpg"},{"id":"Seed678","no":678,"hint_en":"Pick up the rock on a ledge about one-fourth of the way down the cliff.","hint_cn":"捡起约1/4高崖壁架上的石头","img":"Korok678.jpg"},{"id":"Seed679","no":679,"hint_en":"Stand near the pinwheel and shoot the balloons.","hint_cn":"站在风车旁射气球","img":"Korok679.jpg"},{"id":"Seed680","no":680,"hint_en":"Solve the block puzzle, making the two patterns identical.","hint_cn":"解开方块拼图，使两图案相同","img":"Korok680.jpg"},{"id":"Seed681","no":681,"hint_en":"Complete the box puzzle.","hint_cn":"完成方块拼图","img":"Korok681.jpg"},{"id":"Seed682","no":682,"hint_en":"Roll a boulder (from uphill to the northwest) into the hole.","hint_cn":"把巨石（西北坡上）滚进坑里","img":"Korok682.jpg"},{"id":"Seed683","no":683,"hint_en":"Stand near the pinwheel and shoot the balloons around you. Using a long ranged bow is recommended.","hint_cn":"站在风车旁射周围气球。建议用长弓","img":"Korok683.jpg"},{"id":"Seed684","no":684,"hint_en":"Shoot a balloon in a tree.","hint_cn":"射树上气球","img":"Korok684.jpg"},{"id":"Seed685","no":685,"hint_en":"Jump into the water and go under the rock structure as far northwest as you can go. You'll find a pile of leaves to cut away, revealing a rock to pick up. Cold Resistance Level 2 recommended","hint_cn":"跳入水中游到岩石结构最西北。找到树叶堆砍开露出石头捡起。建议耐寒等级2","img":"Korok685.jpg"},{"id":"Seed686","no":686,"hint_en":"Run through flowers 1-5.","hint_cn":"跑花1-5","img":"Korok686.jpg"},{"id":"Seed687","no":687,"hint_en":"Put an apple in the empty bowl.","hint_cn":"把苹果放进空碗","img":"Korok687.jpg"},{"id":"Seed688","no":688,"hint_en":"Under a rock, a fourth down the canyon.","hint_cn":"峡谷1/4处石头底下","img":"Korok688.jpg"},{"id":"Seed689","no":689,"hint_en":"Climb up to the top of the windmill and examine the fairy lights.","hint_cn":"爬上风车顶查看精灵光点","img":"Korok689.jpg"},{"id":"Seed690","no":690,"hint_en":"Shoot an acorn hanging from the lower part of the windmill.","hint_cn":"射风车下部悬挂橡果","img":"Korok690.jpg"},{"id":"Seed691","no":691,"hint_en":"Inside the cave, there's a yellow flower at the bottom of the Leviathan's spine directly behind the Shrine. Follow it to get the Korok Seed. Cold Resistance Level 2 recommended.","hint_cn":"洞内神庙后利维坦脊柱底部有黄花。跟随取克洛格种子。建议耐寒等级2","img":"Korok691.jpg"},{"id":"Seed692","no":692,"hint_en":"Destroy the acorn hanging under an outcrop.","hint_cn":"摧毁悬岩下悬挂橡果","img":"Korok692.jpg"},{"id":"Seed693","no":693,"hint_en":"Shoot the balloons near the windmill.","hint_cn":"射风车旁气球","img":"Korok693.jpg"},{"id":"Seed694","no":694,"hint_en":"Complete the three circles, using the rock lying in one of the circles.","hint_cn":"用其中一圈里的石头完成三个圆圈","img":"Korok694.jpg"},{"id":"Seed695","no":695,"hint_en":"Destroy the acorn in the hole in the side of the large tree.","hint_cn":"摧毁大树侧面洞里橡果","img":"Korok695.jpg"},{"id":"Seed696","no":696,"hint_en":"Stand on the stump, then shoot the flying acorns.","hint_cn":"站树桩上射飞橡果","img":"Korok696.jpg"},{"id":"Seed697","no":697,"hint_en":"Roll a boulder from the west (up the hill) downhill to the east into a small hole.","hint_cn":"从西边（上坡）滚巨石向东进小洞","img":"Korok697.jpg"},{"id":"Seed698","no":698,"hint_en":"Under a rock behind some destructible boulders.","hint_cn":"可碎石后石头底下","img":"Korok698.jpg"},{"id":"Seed699","no":699,"hint_en":"Catch the flying lights.","hint_cn":"抓住飞光","img":"Korok699.jpg"},{"id":"Seed700","no":700,"hint_en":"Follow the flower order. The third flower is behind some bushes.","hint_cn":"按花的顺序。第三朵花在灌木丛后","img":"Korok700.jpg"},{"id":"Seed701","no":701,"hint_en":"Lift the rock up.","hint_cn":"举起石头","img":"Korok701.jpg"},{"id":"Seed702","no":702,"hint_en":"Climb to the top of the rock sculpture of Daruk's head to find the seed platform. Race east towards the ring before the time runs out.","hint_cn":"爬上达尔克头岩石雕塑顶找种子平台。赛跑向东至圆环别超时","img":"Korok702.jpg"},{"id":"Seed703","no":703,"hint_en":"Complete the magnetic puzzle here using Magnesis.","hint_cn":"用磁力完成这里磁力拼图","img":"Korok703.jpg"},{"id":"Seed704","no":704,"hint_en":"Stand on the tree stump with the pinwheel. There will be an acorn jumping at the top of one of the trees. Shoot it.","hint_cn":"站风车树桩上。一棵树顶有跳跃橡果。射它","img":"Korok704.jpg"},{"id":"Seed705","no":705,"hint_en":"Pick up the rock on the shore.","hint_cn":"捡起岸边石头","img":"Korok705.jpg"},{"id":"Seed706","no":706,"hint_en":"Shoot the acorn hidden in the tree.","hint_cn":"射树里藏的橡果","img":"Korok706.jpg"},{"id":"Seed707","no":707,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok707.jpg"},{"id":"Seed708","no":708,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok708.jpg"},{"id":"Seed709","no":709,"hint_en":"Shoot the acorn hanging under the bridge.","hint_cn":"射桥下悬挂橡果","img":"Korok709.jpg"},{"id":"Seed710","no":710,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok710.jpg"},{"id":"Seed711","no":711,"hint_en":"Destroy the acorn in the hole in the side of a tree.","hint_cn":"摧毁树侧面洞里橡果","img":"Korok711.jpg"},{"id":"Seed712","no":712,"hint_en":"Pop the balloon on top of the tree.","hint_cn":"顶树爆气球","img":"Korok712.jpg"},{"id":"Seed713","no":713,"hint_en":"Shoot the acorn hanging from the wreck of a carriage.","hint_cn":"射马车站残骸悬挂橡果","img":"Korok713.jpg"},{"id":"Seed714","no":714,"hint_en":"Examine the fairy lights at the top of the flagpole.","hint_cn":"查看旗杆顶精灵光点","img":"Korok714.jpg"},{"id":"Seed715","no":715,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok715.jpg"},{"id":"Seed716","no":716,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok716.jpg"},{"id":"Seed717","no":717,"hint_en":"Under a rock on top of the large tree.","hint_cn":"大树顶石头底下","img":"Korok717.jpg"},{"id":"Seed718","no":718,"hint_en":"Place a Rusty Shield in the offering bowl. One is nearby, to the southeast.","hint_cn":"在供碗放锈盾。附近东南有一个","img":"Korok718.jpg"},{"id":"Seed719","no":719,"hint_en":"Shoot the acorn that's at the end of the hollow log. Cold Resistance Level 2 recommended","hint_cn":"射空心原木末端橡果。建议耐寒等级2","img":"Korok719.jpg"},{"id":"Seed720","no":720,"hint_en":"Dive into the circle.","hint_cn":"跳入圆圈","img":"Korok720.jpg"},{"id":"Seed721","no":721,"hint_en":"Shoot the balloon under the alcove where the river begins.","hint_cn":"射河流起点凹处下气球","img":"Korok721.jpg"},{"id":"Seed722","no":722,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok722.jpg"},{"id":"Seed723","no":723,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok723.jpg"},{"id":"Seed724","no":724,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok724.jpg"},{"id":"Seed725","no":725,"hint_en":"Climb up the long bare tree to examine the fairy lights.","hint_cn":"爬上长枯树查看精灵光点","img":"Korok725.jpg"},{"id":"Seed726","no":726,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok726.jpg"},{"id":"Seed727","no":727,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok727.jpg"},{"id":"Seed728","no":728,"hint_en":"Catch the fairy lights that run around in the area","hint_cn":"抓住绕区域跑的精灵光点","img":"Korok728.jpg"},{"id":"Seed729","no":729,"hint_en":"Under the rock on top of the tree.","hint_cn":"树顶石头底下","img":"Korok729.jpg"},{"id":"Seed730","no":730,"hint_en":"Lift up the rock.","hint_cn":"举起石头","img":"Korok730.jpg"},{"id":"Seed731","no":731,"hint_en":"To the east of the seed marker there's a ledge with the seed platform on it. Race to the ring.","hint_cn":"种子标记东边有壁架带种子平台。赛跑至圆环","img":"Korok731.jpg"},{"id":"Seed732","no":732,"hint_en":"Throw a rock into the ring of rocks in the river.","hint_cn":"把石头扔进河里石圈","img":"Korok732.jpg"},{"id":"Seed733","no":733,"hint_en":"Under a rock behind some cracked boulders.","hint_cn":"裂纹巨石后石头底下","img":"Korok733.jpg"},{"id":"Seed734","no":734,"hint_en":"Put a Spicy Pepper in the offering bowl that is missing one.","hint_cn":"把辣椒放进缺的供碗","img":"Korok734.jpg"},{"id":"Seed735","no":735,"hint_en":"Run through the flower patches in order from 1 to 5.","hint_cn":"按1到5顺序跑花丛","img":"Korok735.jpg"},{"id":"Seed736","no":736,"hint_en":"In a cave with Luminous Ore, blow up the boulders and pick up the small rock behind them. the cave can be found next to the big tree.","hint_cn":"在夜光石洞里炸巨石捡起后面小石头。洞在大树旁","img":"Korok736.jpg"},{"id":"Seed737","no":737,"hint_en":"Stand by the pinwheel, shoot the three balloons.","hint_cn":"站风车旁射三个气球","img":"Korok737.jpg"},{"id":"Seed738","no":738,"hint_en":"Three trees stand on top of this plateau. Pluck the apples one of them so that it matches the other two trees.","hint_cn":"这个高原顶三棵树。摘其中一棵苹果使其和另外两棵匹配","img":"Korok738.jpg"},{"id":"Seed739","no":739,"hint_en":"Move the large boulder surrounded by smaller rocks. Then lift up the rock underneath it to reveal a Korok.","hint_cn":"移开小石块包围的巨石。然后举起下面石头露出克洛格","img":"Korok739.jpg"},{"id":"Seed740","no":740,"hint_en":"Climb to the top of the tallest pine tree here and examine the sparkles.","hint_cn":"爬到这里最高松树顶查看闪光","img":"Korok740.jpg"},{"id":"Seed741","no":741,"hint_en":"Examine the flying leaves at the top of the hill.","hint_cn":"查看山顶飞舞树叶","img":"Korok741.jpg"},{"id":"Seed742","no":742,"hint_en":"Pick up the rock on top of the large tree.","hint_cn":"捡起大树顶上石头","img":"Korok742.jpg"},{"id":"Seed743","no":743,"hint_en":"On the side of the cliff, blow up the cracked boulders then lift the small rock hidden behind them.","hint_cn":"崖边炸裂纹巨石然后举起隐藏后面小石头","img":"Korok743.jpg"},{"id":"Seed744","no":744,"hint_en":"Follow the flower trail that starts in the north section of the ruins.","hint_cn":"跟随遗迹北段开始的花径","img":"Korok744.jpg"},{"id":"Seed745","no":745,"hint_en":"Race that starts from the under the east end of the bridge to finish under the west end of the bridge.","hint_cn":"赛跑从桥东端下开始，到桥西端下结束","img":"Korok745.jpg"},{"id":"Seed746","no":746,"hint_en":"Race from a cliff to the north to the finish to the south.","hint_cn":"赛跑从北边悬崖到南边终点","img":"Korok746.jpg"},{"id":"Seed747","no":747,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok747.jpg"},{"id":"Seed748","no":748,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok748.jpg"},{"id":"Seed749","no":749,"hint_en":"Race from a cliff to the south to the finish to the north.","hint_cn":"赛跑从南边悬崖到北边终点","img":"Korok749.jpg"},{"id":"Seed750","no":750,"hint_en":"On the side of the cliff, blow up the cracked boulders then lift the small rock hidden behind them.","hint_cn":"崖边炸裂纹巨石然后举起隐藏后面小石头","img":"Korok750.jpg"},{"id":"Seed751","no":751,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok751.jpg"},{"id":"Seed752","no":752,"hint_en":"Catch the fairy lights at the top of the bare tree.","hint_cn":"抓住秃树顶精灵光点","img":"Korok752.jpg"},{"id":"Seed753","no":753,"hint_en":"At ground level, blow up the cracked boulders then lift the small rock hidden behind them.","hint_cn":"地面层炸裂纹巨石然后举起隐藏后面小石头","img":"Korok753.jpg"},{"id":"Seed754","no":754,"hint_en":"Blast the rock wall, enter the cave and pick up the rock.","hint_cn":"炸岩壁进洞捡起石头","img":"Korok754.jpg"},{"id":"Seed755","no":755,"hint_en":"On top of the giant mushroom, complete the stone circle using 3 nearby rocks.","hint_cn":"在大蘑菇顶上用附近3块石头完成石圈","img":"Korok755.jpg"},{"id":"Seed756","no":756,"hint_en":"Follow the trail of flowers that start on top of the large mushroom tree to the southwest. Note, the final flower is on the floor, not a mushroom.","hint_cn":"跟随西南大蘑菇树顶开始的花径。注意最后一朵花在地面不是蘑菇上","img":"Korok756.jpg"},{"id":"Seed757","no":757,"hint_en":"Race from ground level just north up to the small mushroom.","hint_cn":"赛跑从地面正北到小蘑菇","img":"Korok757.jpg"},{"id":"Seed758","no":758,"hint_en":"Shoot the balloon hanging under the huge mushroom tree.","hint_cn":"射大蘑菇树下悬挂气球","img":"Korok758.jpg"},{"id":"Seed759","no":759,"hint_en":"Shoot the balloon hanging under the huge mushroom tree.","hint_cn":"射大蘑菇树下悬挂气球","img":"Korok759.jpg"},{"id":"Seed760","no":760,"hint_en":"Inside the Forgotten Temple, behind the Goddess Statue's head, north of the shrine, lift the rock.","hint_cn":"在遗忘神庙，女神像头后、神庙北側，举起石头","img":"Korok760.jpg"},{"id":"Seed761","no":761,"hint_en":"Shoot the acorn in the hole in the side of the tree.","hint_cn":"射树侧面洞里橡果","img":"Korok761.jpg"},{"id":"Seed762","no":762,"hint_en":"Race from a large mushroom tree to the southeast, finish on topside of another large mushroom tree.","hint_cn":"赛跑从东南大蘑菇树开始，结束在另一个大蘑菇树顶","img":"Korok762.jpg"},{"id":"Seed763","no":763,"hint_en":"Run through the flower patches 1-5.","hint_cn":"跑花丛1-5","img":"Korok763.jpg"},{"id":"Seed764","no":764,"hint_en":"Move the slab, and pick up the rock under it.","hint_cn":"移动石板，捡起下面石头","img":"Korok764.jpg"},{"id":"Seed765","no":765,"hint_en":"Race from the beach to the east of the seed location to the yellow ring on the rock.","hint_cn":"赛跑从种子位置东海滩到岩石上黄圈","img":"Korok765.jpg"},{"id":"Seed766","no":766,"hint_en":"Under a rock on top of the tree.","hint_cn":"树顶石头底下","img":"Korok766.jpg"},{"id":"Seed767","no":767,"hint_en":"Use the updraft to float straight into the air. Look under the nearby rock formation and shoot the balloon.","hint_cn":"用上升气流直飘空中。看附近岩石构造下射气球","img":"Korok767.jpg"},{"id":"Seed768","no":768,"hint_en":"Reach the circle before the time limit. The seed platform is on the curved ledge to the southwest.","hint_cn":"限时到圆环。种子平台在西南弧形壁架上","img":"Korok768.jpg"},{"id":"Seed769","no":769,"hint_en":"One cactus has too many voltfruit. Make it look like the other two.","hint_cn":"一棵仙人掌电量果太多。让它和另外两棵一样","img":"Korok769.jpg"},{"id":"Seed770","no":770,"hint_en":"Shoot the balloon in the tree.","hint_cn":"射树上气球","img":"Korok770.jpg"},{"id":"Seed771","no":771,"hint_en":"Solve the Magnesis puzzle on the side of the cliff wall.","hint_cn":"解崖壁磁力拼图","img":"Korok771.jpg"},{"id":"Seed772","no":772,"hint_en":"Under a rock behind some destructible boulders.","hint_cn":"可碎石后石头底下","img":"Korok772.jpg"},{"id":"Seed773","no":773,"hint_en":"Shoot the balloons that appear near the pinwheel.","hint_cn":"射风车旁出现的气球","img":"Korok773.jpg"},{"id":"Seed774","no":774,"hint_en":"Under a rock on the top of the peak.","hint_cn":"峰顶顶石头底下","img":"Korok774.jpg"},{"id":"Seed775","no":775,"hint_en":"Shoot the three balloons, standing next to the pinwheel.","hint_cn":"站风车旁射三个气球","img":"Korok775.jpg"},{"id":"Seed776","no":776,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok776.jpg"},{"id":"Seed777","no":777,"hint_en":"Follow the trail of flowers starting uphill to the southwest.","hint_cn":"跟随西南上坡开始的花径","img":"Korok777.jpg"},{"id":"Seed778","no":778,"hint_en":"The seed platform is way to the north, at the southwest corner of the plateau the Hebra West Summit is on, next to a large flag. Shield surf or paraglide to the end location.","hint_cn":"种子平台在北边很远，在海布拉西峰高原西南角，大旗帜旁。盾滑或滑翔到终点","img":"Korok778.jpg"},{"id":"Seed779","no":779,"hint_en":"Shoot the Hylian symbol on the north side of the wall, above the gate.","hint_cn":"射门上方北墙希卡族纹章","img":"Korok779.jpg"},{"id":"Seed780","no":780,"hint_en":"There is a Korok platform on top of the wall to the south of the fountain, west of the gate. Glide from there to the fountain.","hint_cn":"喷泉南、门西墙上有克洛格平台。从那里滑翔到喷泉","img":"Korok780.jpg"},{"id":"Seed781","no":781,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok781.jpg"},{"id":"Seed782","no":782,"hint_en":"Under a rock behind the shrine.","hint_cn":"神庙后石头底下","img":"Korok782.jpg"},{"id":"Seed783","no":783,"hint_en":"Go to the southeastern corner of the bridge and move underneath it, to where a single rock is. Pick up the rock to reveal the Korok.","hint_cn":"到桥东南角钻到桥下，有块石头。捡起露出克洛格","img":"Korok783.jpg"},{"id":"Seed784","no":784,"hint_en":"Complete the rock circle with the rock that is downhill from the circle, next to a dead guardian.","hint_cn":"用圆圈坡下死守护者旁石头完成石圈","img":"Korok784.jpg"},{"id":"Seed785","no":785,"hint_en":"Pick up rock on top of destroyed structure.","hint_cn":"捡废墟顶上石头","img":"Korok785.jpg"},{"id":"Seed786","no":786,"hint_en":"In a corridor under the First Gatehouse, break the bombable wall, then shoot the acorn with an arrow.","hint_cn":"在第一门屋下走廊，炸开可炸墙，然后射箭射橡果","img":"Korok786.jpg"},{"id":"Seed787","no":787,"hint_en":"Place a Bird Egg in front of each statue.","hint_cn":"每个雕像前放一颗鸟蛋","img":"Korok787.jpg"},{"id":"Seed788","no":788,"hint_en":"Lift the rock found halfway down the shaft.","hint_cn":"举起竖井半腰石头","img":"Korok788.jpg"},{"id":"Seed789","no":789,"hint_en":"On top of the gate to Hyrule Castle is a rock. Lift the rock.","hint_cn":"海拉鲁城堡门上有块石头。举起","img":"Korok789.jpg"},{"id":"Seed790","no":790,"hint_en":"Follow the flower trail starting under the bridge on the southern side of the moat.","hint_cn":"跟随护城河南侧桥下开始的花径","img":"Korok790.jpg"},{"id":"Seed791","no":791,"hint_en":"Get rid of the leaves and pick up the rock underneath.","hint_cn":"去掉树叶捡起下面石头","img":"Korok791.jpg"},{"id":"Seed792","no":792,"hint_en":"Thaw the ice block and examine the glittering leaves. Cold Resistance Level 2 recommended","hint_cn":"融化冰块查看闪光树叶。建议耐寒等级2","img":"Korok792.jpg"},{"id":"Seed793","no":793,"hint_en":"On top of the temple. Under a rock behind the bombable boulders.","hint_cn":"神庙顶上。可炸巨石后石头底下","img":"Korok793.jpg"},{"id":"Seed794","no":794,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok794.jpg"},{"id":"Seed795","no":795,"hint_en":"Jump the three fences while riding. This can also be done with the Master Cycle Zero using the Zero Jump","hint_cn":"骑马跳三个栅栏。也可以用摩托 zero jump","img":"Korok795.jpg"},{"id":"Seed796","no":796,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok796.jpg"},{"id":"Seed797","no":797,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok797.jpg"},{"id":"Seed798","no":798,"hint_en":"Clear the apples on the tree with too many to have the same amount as the others.","hint_cn":"清理苹果过多树上的苹果使其和其他一样多","img":"Korok798.jpg"},{"id":"Seed799","no":799,"hint_en":"Complete the rock square.","hint_cn":"完成石方","img":"Korok799.jpg"},{"id":"Seed800","no":800,"hint_en":"Remove the rock slab, then pick up the rock.","hint_cn":"移开石板，然后捡起石头","img":"Korok800.jpg"},{"id":"Seed801","no":801,"hint_en":"Knock the boulder off, then pick up the little rock.","hint_cn":"敲落巨石然后捡小石头","img":"Korok801.jpg"},{"id":"Seed802","no":802,"hint_en":"Look under the rock bridge to find a small ledge with a rock on it. Pick up the rock to reveal the Korok.","hint_cn":"看石桥下找带石头小壁架。捡起石头露出克洛格","img":"Korok802.jpg"},{"id":"Seed803","no":803,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok803.jpg"},{"id":"Seed804","no":804,"hint_en":"Destroy the acorn inside the hollow of the tree log.","hint_cn":"摧毁树洞里橡果","img":"Korok804.jpg"},{"id":"Seed805","no":805,"hint_en":"The seed platform is to the north, just west of where the water begins, at the highest point overlooking the falls. Race to the ring.","hint_cn":"种子平台在北边，水开始处西边不远，俯瞰瀑布最高点。赛跑至圆环","img":"Korok805.jpg"},{"id":"Seed806","no":806,"hint_en":"Shoot the balloon down by the water.","hint_cn":"射水边气球","img":"Korok806.jpg"},{"id":"Seed807","no":807,"hint_en":"Destroy the acorn in the hollow of the tree log.","hint_cn":"摧毁树洞里橡果","img":"Korok807.jpg"},{"id":"Seed808","no":808,"hint_en":"Located on a higher ledge than the nearby seed. There are two blocks and pile of leaves here. Disturb the leaves and pick up the rock.","hint_cn":"位于比附近种子更高壁架。这里有两个方块和树叶堆。拨树叶捡石头","img":"Korok808.jpg"},{"id":"Seed809","no":809,"hint_en":"Located on a lower ledge than the nearby seed. Move the door with Magnesis to uncover a rock to pick up.","hint_cn":"位于比附近种子更低壁架。用磁力移门露出石头捡起","img":"Korok809.jpg"},{"id":"Seed810","no":810,"hint_en":"Drop down from the southern ledge with the cannons to find a pile of leaves. Disturb the leaves and pick up the rock.","hint_cn":"从带炮南壁架跳下找树叶堆。拨树叶捡石头","img":"Korok810.jpg"},{"id":"Seed811","no":811,"hint_en":"Under the bridge, move the rock slab, then pick up the rock.","hint_cn":"桥下移动石板然后捡起石头","img":"Korok811.jpg"},{"id":"Seed812","no":812,"hint_en":"Blow up the rock wall and lift up the small rock that was hidden behind it.","hint_cn":"炸岩壁举起隐藏后面小石头","img":"Korok812.jpg"},{"id":"Seed813","no":813,"hint_en":"Blow up the boulders, lift up the rock underneath.","hint_cn":"炸巨石举起下面石头","img":"Korok813.jpg"},{"id":"Seed814","no":814,"hint_en":"Climb a tall pine tree and examine the glowing leaves to find the Korok.","hint_cn":"爬高松树查看发光树叶找克洛格","img":"Korok814.jpg"},{"id":"Seed815","no":815,"hint_en":"Stand next to the pinwheel atop the tree and shoot the balloons.","hint_cn":"站树顶风车旁射气球","img":"Korok815.jpg"},{"id":"Seed816","no":816,"hint_en":"An invisible Korok will be running around the area. Interact with it and collect the Korok seed.","hint_cn":"一个隐形克洛格绕区域跑。互动收集种子","img":"Korok816.jpg"},{"id":"Seed817","no":817,"hint_en":"Clear the leaves and pick up the rock to find the Korok.","hint_cn":"清理树叶捡起石头找克洛格","img":"Korok817.jpg"},{"id":"Seed818","no":818,"hint_en":"Disturb the leaves with a bladed weapon then lift up the small rock hidden underneath them.","hint_cn":"用斩草武器拨树叶然后举起隐藏下面小石头","img":"Korok818.jpg"},{"id":"Seed819","no":819,"hint_en":"The seed platform is on the skull. Race to the ring.","hint_cn":"种子平台在骷髅上。赛跑至圆环","img":"Korok819.jpg"},{"id":"Seed820","no":820,"hint_en":"Use a bomb on the breakable wall then lift the rock.","hint_cn":"在可破墙用炸弹然后举起石头","img":"Korok820.jpg"},{"id":"Seed821","no":821,"hint_en":"Find the seed platform up hill. Race in time to the target to reveal the Korok.","hint_cn":"上坡找种子平台。及时赛跑至目标露出克洛格","img":"Korok821.jpg"},{"id":"Seed822","no":822,"hint_en":"Throw one of the rocks into the rock circle.","hint_cn":"把其中一块石头扔进石圈","img":"Korok822.jpg"},{"id":"Seed823","no":823,"hint_en":"Complete the Magnesis cube puzzle. The metal cube is located on the eastern edge of the canyon floor, the template on the northeast side of the pond, and the puzzle is found on the island center.","hint_cn":"完成磁力方块拼图。金属方块在峡谷底东缘，模板在池塘东北，拼图在中心岛","img":"Korok823.jpg"},{"id":"Seed824","no":824,"hint_en":"Destroy the acorn in the hollow of the log.","hint_cn":"摧毁树洞里橡果","img":"Korok824.jpg"},{"id":"Seed825","no":825,"hint_en":"Solve the block puzzle.","hint_cn":"解开方块拼图","img":"Korok825.jpg"},{"id":"Seed826","no":826,"hint_en":"Lift the stone on top of the fountain.","hint_cn":"举起喷泉顶上石头","img":"Korok826.jpg"},{"id":"Seed827","no":827,"hint_en":"Stand on the stump with the pinwheel and shoot the 3 targets that are circling the nearby trees.","hint_cn":"站风车树桩上射绕附近树盘旋3个靶子","img":"Korok827.jpg"},{"id":"Seed828","no":828,"hint_en":"Lift the rock in the center of the dead trees.","hint_cn":"举起枯树中心石头","img":"Korok828.jpg"},{"id":"Seed829","no":829,"hint_en":"Shoot the acorn inside the hollow tree log.","hint_cn":"射空心树洞里橡果","img":"Korok829.jpg"},{"id":"Seed830","no":830,"hint_en":"Dive/jump/fall into the circle of water lilies.","hint_cn":"跳入/跳入/跌入睡莲圈","img":"Korok830.jpg"},{"id":"Seed831","no":831,"hint_en":"Under a rock behind some destructible boulders.","hint_cn":"可碎石后石头底下","img":"Korok831.jpg"},{"id":"Seed832","no":832,"hint_en":"Pick up the rock on the northernmost pillar and move it to the upper edge of the pillar so it matches the rock placement on the other pillars.","hint_cn":"捡起最北柱上石头移到柱上缘使其和其他柱石头摆放匹配","img":"Korok832.jpg"},{"id":"Seed833","no":833,"hint_en":"Under a rock under a pile of leaves.","hint_cn":"树叶堆下石头底下","img":"Korok833.jpg"},{"id":"Seed834","no":834,"hint_en":"Roll a boulder into the lava pond below.","hint_cn":"把巨石滚进下方熔岩池","img":"Korok834.jpg"},{"id":"Seed835","no":835,"hint_en":"Complete the puzzle using Magnesis.","hint_cn":"用磁力完成拼图","img":"Korok835.jpg"},{"id":"Seed836","no":836,"hint_en":"Carry a rock through the shallow water to the rock circle and throw it in.","hint_cn":"搬石头过浅水到石圈扔进","img":"Korok836.jpg"},{"id":"Seed837","no":837,"hint_en":"Follow the flower trail. It starts west-northwest of Sturnida Secret Hot Spring, halfway up the cliff. The trail leads south along the cliff face.","hint_cn":"跟随花径。起点在思库达秘泉西北偏西半崖。沿崖壁向南","img":"Korok837.jpg"},{"id":"Seed838","no":838,"hint_en":"The flower trail starts a short distance southeast and down the cliff. Follow it up the cliff.","hint_cn":"花径从东南不远处崖下开始。跟随爬上悬崖","img":"Korok838.jpg"},{"id":"Seed839","no":839,"hint_en":"Climb the dead tree and interact with the fairy lights.","hint_cn":"爬枯树与精灵光点互动","img":"Korok839.jpg"},{"id":"Seed840","no":840,"hint_en":"Examine the fairy lights on the top of the dead tree. Cold Resistance Level 2 recommended","hint_cn":"查看枯树顶精灵光点。建议耐寒等级2","img":"Korok840.jpg"},{"id":"Seed841","no":841,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok841.jpg"},{"id":"Seed842","no":842,"hint_en":"Complete the rock pattern using a nearby rock.","hint_cn":"用附近石头完成石头图案","img":"Korok842.jpg"},{"id":"Seed843","no":843,"hint_en":"Climb up the tallest pillar in the northeast section and pick up the rock at the top.","hint_cn":"爬上东北最高柱顶捡石头","img":"Korok843.jpg"},{"id":"Seed844","no":844,"hint_en":"Dive into the ring of flowers in the water next to the bridge.","hint_cn":"跳入桥旁水中花圈","img":"Korok844.jpg"},{"id":"Seed845","no":845,"hint_en":"Climb to the top of the tree and examine the swirling leaves.","hint_cn":"爬到树顶查看旋转树叶","img":"Korok845.jpg"},{"id":"Seed846","no":846,"hint_en":"Stand near the pinwheel and shoot the acorn. Cold Resistance Level 2 recommended","hint_cn":"站在风车旁射橡果。建议耐寒等级2","img":"Korok846.jpg"},{"id":"Seed847","no":847,"hint_en":"Thaw the ice block and examine the fairy lights. Cold Resistance Level 2 recommended","hint_cn":"融化冰块查看精灵光点。建议耐寒等级2","img":"Korok847.jpg"},{"id":"Seed848","no":848,"hint_en":"Shoot the balloon that hangs high up under a cliff.","hint_cn":"射高崖下悬挂气球","img":"Korok848.jpg"},{"id":"Seed849","no":849,"hint_en":"Pick up a rock.","hint_cn":"捡起石头","img":"Korok849.jpg"},{"id":"Seed850","no":850,"hint_en":"Thaw the ice block and examine the glittering leaves.","hint_cn":"融化冰块查看闪光树叶","img":"Korok850.jpg"},{"id":"Seed851","no":851,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok851.jpg"},{"id":"Seed852","no":852,"hint_en":"Examine the glittering leaves at the top of the dead tree.","hint_cn":"查看枯树顶闪光树叶","img":"Korok852.jpg"},{"id":"Seed853","no":853,"hint_en":"Examine the fairy lights at the top of the tree.","hint_cn":"查看树顶精灵光点","img":"Korok853.jpg"},{"id":"Seed854","no":854,"hint_en":"Follow the trail of flowers that starts next to the road to the north.","hint_cn":"跟随路北稍东开始的花径","img":"Korok854.jpg"},{"id":"Seed855","no":855,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok855.jpg"},{"id":"Seed856","no":856,"hint_en":"Snow boulders can be carried. Put one in the hole below.","hint_cn":"雪球可搬。放一个到下面坑里","img":"Korok856.jpg"},{"id":"Seed857","no":857,"hint_en":"Destroy the acorn in the hollow in the tree log.","hint_cn":"摧毁树洞里橡果","img":"Korok857.jpg"},{"id":"Seed858","no":858,"hint_en":"Under a rock.","hint_cn":"石头底下","img":"Korok858.jpg"},{"id":"Seed859","no":859,"hint_en":"Catch the fairy lights.","hint_cn":"抓住精灵光点","img":"Korok859.jpg"},{"id":"Seed860","no":860,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok860.jpg"},{"id":"Seed861","no":861,"hint_en":"Use the nearby rock to complete the rock circle.","hint_cn":"用附近石头完成石圈","img":"Korok861.jpg"},{"id":"Seed862","no":862,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok862.jpg"},{"id":"Seed863","no":863,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok863.jpg"},{"id":"Seed864","no":864,"hint_en":"Break the wall, then lift the stone.","hint_cn":"破墙然后举起石头","img":"Korok864.jpg"},{"id":"Seed865","no":865,"hint_en":"Find the pinwheel inside the skull, look outside the eye to find the target balloon. Shoot it with an arrow to reveal the Korok.","hint_cn":"在骷髅里找风车，看眼睛外找目标气球。射箭露出克洛格","img":"Korok865.jpg"},{"id":"Seed866","no":866,"hint_en":"Complete the stone circle.","hint_cn":"完成石圈","img":"Korok866.jpg"},{"id":"Seed867","no":867,"hint_en":"Break the wall, lift the stone.","hint_cn":"破墙举起石头","img":"Korok867.jpg"},{"id":"Seed868","no":868,"hint_en":"Climb the pillar, pick up the rock.","hint_cn":"爬柱捡起石头","img":"Korok868.jpg"},{"id":"Seed869","no":869,"hint_en":"Use the rock above to complete the stone circle below.","hint_cn":"用上方石头完成下方石圈","img":"Korok869.jpg"},{"id":"Seed870","no":870,"hint_en":"Lift the rock to reveal the Korok.","hint_cn":"举起石头露出克洛格","img":"Korok870.jpg"},{"id":"Seed871","no":871,"hint_en":"Lift the rock that's located under the rock sculpture's armpit.","hint_cn":"举起岩石雕塑腋窝下石头","img":"Korok871.jpg"},{"id":"Seed872","no":872,"hint_en":"From the city entrance, look up and to the left. Climb into the mouth of the southwest goron in the rock structure, and examine the fairy lights.","hint_cn":"从城入口看左上。爬进西南哥隆岩石结构嘴里查看精灵光点","img":"Korok872.jpg"},{"id":"Seed873","no":873,"hint_en":"Examine the fairy lights on top of the stone ribcage.","hint_cn":"查看石肋骨顶上精灵光点","img":"Korok873.jpg"},{"id":"Seed874","no":874,"hint_en":"Shoot the acorn in the hole in the tree.","hint_cn":"射树洞里橡果","img":"Korok874.jpg"},{"id":"Seed875","no":875,"hint_en":"Pick up the rock.","hint_cn":"捡起石头","img":"Korok875.jpg"},{"id":"Seed876","no":876,"hint_en":"Roll the boulder to the hole.","hint_cn":"把巨石滚到坑里","img":"Korok876.jpg"},{"id":"Seed877","no":877,"hint_en":"Shoot the acorn hidden in the alcove under the bridge to the gate to Hyrule Castle.","hint_cn":"射通往海拉鲁城堡门桥下凹处藏的橡果","img":"Korok877.jpg"},{"id":"Seed878","no":878,"hint_en":"Race to the finish from the platform to the west-southwest. Use the updraft and your paraglider to gain height quickly.","hint_cn":"从西偏南平台赛跑至终点。用上升气流和滑翔伞快速升高","img":"Korok878.jpg"},{"id":"Seed879","no":879,"hint_en":"Shoot the stone Coat of Arms to reveal the Korok.","hint_cn":"射石纹章露出克洛格","img":"Korok879.jpg"},{"id":"Seed880","no":880,"hint_en":"Climb the platform and lift the rock.","hint_cn":"爬上平台举起石头","img":"Korok880.jpg"},{"id":"Seed881","no":881,"hint_en":"Shoot the acorn in the hole in the tree.","hint_cn":"射树洞里橡果","img":"Korok881.jpg"},{"id":"Seed882","no":882,"hint_en":"Lift the rock up.","hint_cn":"举起石头","img":"Korok882.jpg"},{"id":"Seed883","no":883,"hint_en":"Interact with the fairy lights.","hint_cn":"与精灵光点互动","img":"Korok883.jpg"},{"id":"Seed884","no":884,"hint_en":"Shoot the acorn in the tree trunk.","hint_cn":"射树干里橡果","img":"Korok884.jpg"},{"id":"Seed885","no":885,"hint_en":"Shoot the acorn in the log.","hint_cn":"射原木里橡果","img":"Korok885.jpg"},{"id":"Seed886","no":886,"hint_en":"Shoot the acorn in the hollow log.","hint_cn":"射空心原木里橡果","img":"Korok886.jpg"},{"id":"Seed887","no":887,"hint_en":"Bomb the breakable wall high up on the cliffside, then lift the stone.","hint_cn":"炸高崖边可破墙然后举起石头","img":"Korok887.jpg"},{"id":"Seed888","no":888,"hint_en":"Lift the stone.","hint_cn":"举起石头","img":"Korok888.jpg"},{"id":"Seed889","no":889,"hint_en":"Enter the East Passage. Just before the room with the Talus, you find blocks of ice along a wall. Melt the largest ice block, then examine the fairy lights.","hint_cn":"进入东通道。在岩石巨人房间前，沿墙有冰块。融化最大冰块然后查看精灵光点","img":"Korok889.jpg"},{"id":"Seed890","no":890,"hint_en":"This ledge is just below the last curve in the path before it enters the castle. Bomb the breakable wall, then lift the stone.","hint_cn":"这个壁架就在进城堡前路最后弯道下方。炸可破墙然后举起石头","img":"Korok890.jpg"},{"id":"Seed891","no":891,"hint_en":"Climb to the top of the spire above the First Gatehouse.","hint_cn":"爬到第一门屋上方尖塔顶","img":"Korok891.jpg"},{"id":"Seed892","no":892,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok892.jpg"},{"id":"Seed893","no":893,"hint_en":"Throw a rock into the ring of stones in the water.","hint_cn":"把石头扔进水中石圈","img":"Korok893.jpg"},{"id":"Seed894","no":894,"hint_en":"Lift the rock.","hint_cn":"举起石头","img":"Korok894.jpg"},{"id":"Seed895","no":895,"hint_en":"Solve the block puzzle. Half of it is underwater nearby.","hint_cn":"解开方块拼图。一半在附近水下","img":"Korok895.jpg"},{"id":"Seed896","no":896,"hint_en":"On a rock ledge just above the water, bomb the breakable wall, then lift the stone.","hint_cn":"在水上方岩石壁架上炸可破墙然后举起石头","img":"Korok896.jpg"},{"id":"Seed897","no":897,"hint_en":"Lift the rock under the bridge.","hint_cn":"举起桥下石头","img":"Korok897.jpg"},{"id":"Seed898","no":898,"hint_en":"Pick apples on the third tree to make it match the other two.","hint_cn":"在第三棵树摘苹果使其和另外两棵匹配","img":"Korok898.jpg"},{"id":"Seed899","no":899,"hint_en":"Shoot the acorn.","hint_cn":"射橡果","img":"Korok899.jpg"},{"id":"Seed900","no":900,"hint_en":"Stand near the pinwheel and shoot the balloon.","hint_cn":"站在风车旁射气球","img":"Korok900.jpg"}]};
